-- Quality → Audits as an audit programme with standard-based questionnaires.
--
-- A. Questionnaires («Ερωτηματολόγια επιθεώρησης»)
--    quality_audit_templates            a questionnaire: standard and version, title,
--                                       scope, the hospital areas it applies to,
--                                       active, version. organization_id null and
--                                       is_system = the platform library every
--                                       hospital reads (the Platform Owner keeps it);
--                                       a hospital's own copy points at it (based_on)
--                                       and is edited by its Quality managers. The
--                                       same pattern as prevention_bundle_templates.
--    quality_audit_template_questions   its questions in order: chapter and clause
--                                       reference, the question, guidance, the
--                                       evidence to see, weight, critical flag, the
--                                       areas it applies to (none = everywhere).
-- B. The programme: quality_audits gains the questionnaire it uses (and a snapshot
--    of its title and version), the standard, the clauses in scope, the planned
--    month when the day is not fixed, the risk level and frequency, the opening and
--    closing meetings, the auditee's representative, the conclusion, the audit it
--    follows up and where it came from; audit_kind: internal, external,
--    certification or supplier (audit_type stays internal / external).
--    quality_audit_team_members: the team (employees, or external auditors by
--    name) with their role.
-- C. Answers: quality_audit_checklist_items keeps one row per question: result on
--    four values (yes = Συμμορφώνεται, partial = Μερική, no = Μη συμμόρφωση,
--    na = Δεν εφαρμόζεται; answer keeps yes / no / na for earlier readers), the
--    question's clause, chapter, guidance, evidence asked and seen, weight,
--    critical flag, the finding class, and whether it was asked on the spot
--    (ad hoc, e.g. a FileMaker question).
-- D. Findings: the class (major / minor / observation / opportunity), the question
--    it came from, its clause and standard, a due date, the verification of
--    effectiveness and the follow-up audit.
-- E. The seed: one questionnaire per chosen standard (ISO 9001, ISO 15224,
--    HACCP / ISO 22000, ISO 15189, TEMOS, JCI), generated from
--    src/features/quality/audits/seed/*.js (tests/auditProgramme.test.js checks
--    they agree). Audit questions in our own words with
--    the clause reference; never the text of a standard. Editable.
--
-- Row-level security as the other Quality tables: read by Quality readers (and,
-- for a child row, whoever reads its audit), written by Quality managers; the
-- platform library is read by every signed-in user and written by the Platform
-- Owner. No anon.

-- A. Questionnaires -----------------------------------------------------------------

create table if not exists public.quality_audit_templates (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid references public.organizations(id) on delete cascade,
  is_system boolean not null default false,
  based_on uuid references public.quality_audit_templates(id) on delete set null,
  template_key text,
  standard text not null check (standard in ('iso9001', 'iso15224', 'haccp', 'iso15189', 'temos', 'jci', 'other')),
  standard_version text,
  title text not null check (length(btrim(title)) > 1),
  description text,
  scope text,
  department_types text[] not null default '{}' check (department_types <@ array['clinical', 'laboratory', 'kitchen', 'international', 'support', 'management']::text[]),
  active boolean not null default true,
  version integer not null default 1 check (version >= 1),
  source text not null default 'app' check (source in ('app', 'seed', 'filemaker')),
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  constraint quality_audit_templates_system_scope check ((is_system and organization_id is null) or (not is_system and organization_id is not null)),
  constraint quality_audit_templates_title_key unique nulls not distinct (organization_id, title),
  unique (id, organization_id)
);
create index if not exists quality_audit_templates_org_idx on public.quality_audit_templates (organization_id, standard, active);
create index if not exists quality_audit_templates_based_on_idx on public.quality_audit_templates (based_on);

create table if not exists public.quality_audit_template_questions (
  id uuid primary key default gen_random_uuid(),
  template_id uuid not null references public.quality_audit_templates(id) on delete cascade,
  organization_id uuid references public.organizations(id) on delete cascade,
  position integer not null check (position >= 1),
  chapter_ref text not null default '',
  chapter_title text,
  clause_ref text not null default '',
  question text not null check (length(btrim(question)) > 0),
  guidance text,
  evidence text,
  weight numeric(5,2) not null default 1 check (weight > 0),
  critical boolean not null default false,
  areas text[] not null default '{}' check (areas <@ array['clinical', 'laboratory', 'kitchen', 'international', 'support', 'management']::text[]),
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (id, organization_id),
  -- A hospital's question belongs to a questionnaire of the same hospital.
  foreign key (template_id, organization_id) references public.quality_audit_templates(id, organization_id) on delete cascade
);
create index if not exists quality_audit_template_questions_parent_idx on public.quality_audit_template_questions (template_id, position);
create index if not exists quality_audit_template_questions_org_idx on public.quality_audit_template_questions (organization_id);

-- B. The programme ---------------------------------------------------------------------

alter table public.quality_audits
  add column if not exists audit_kind text check (audit_kind is null or audit_kind in ('internal', 'external', 'certification', 'supplier')),
  add column if not exists template_id uuid references public.quality_audit_templates(id) on delete set null,
  add column if not exists template_title text,
  add column if not exists template_version integer,
  add column if not exists standard text check (standard is null or standard in ('iso9001', 'iso15224', 'haccp', 'iso15189', 'temos', 'jci', 'other')),
  add column if not exists clauses_scope text[] not null default '{}',
  add column if not exists planned_month_only boolean not null default false,
  add column if not exists risk_level text check (risk_level is null or risk_level in ('low', 'medium', 'high')),
  add column if not exists frequency_months smallint check (frequency_months is null or frequency_months between 1 and 60),
  add column if not exists opening_meeting_on date,
  add column if not exists opening_attendees text,
  add column if not exists closing_meeting_on date,
  add column if not exists closing_attendees text,
  add column if not exists auditee_representative text,
  add column if not exists conclusion text,
  add column if not exists follow_up_of uuid,
  add column if not exists source text not null default 'app' check (source in ('app', 'seed', 'filemaker'));
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'quality_audits_follow_up_of_fkey') then
    alter table public.quality_audits add constraint quality_audits_follow_up_of_fkey
      foreign key (follow_up_of, organization_id) references public.quality_audits(id, organization_id) on delete set null (follow_up_of);
  end if;
end
$$;
create index if not exists quality_audits_template_idx on public.quality_audits (template_id);
create index if not exists quality_audits_follow_up_idx on public.quality_audits (follow_up_of, organization_id);
create index if not exists quality_audits_standard_idx on public.quality_audits (organization_id, standard, planned_date);

create table if not exists public.quality_audit_team_members (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  audit_id uuid not null,
  position smallint not null default 1 check (position >= 1),
  role text not null default 'member' check (role in ('lead', 'member', 'expert', 'observer')),
  employee_id uuid references public.employees(id) on delete set null,
  full_name text not null check (length(btrim(full_name)) > 0),
  is_external boolean not null default false,
  affiliation text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  foreign key (audit_id, organization_id) references public.quality_audits(id, organization_id) on delete cascade,
  constraint quality_audit_team_members_external check (not is_external or employee_id is null)
);
create index if not exists quality_audit_team_members_audit_idx on public.quality_audit_team_members (audit_id, organization_id, position);
create index if not exists quality_audit_team_members_employee_idx on public.quality_audit_team_members (employee_id);
create index if not exists quality_audit_team_members_org_idx on public.quality_audit_team_members (organization_id);

-- C. Answers ------------------------------------------------------------------------------

alter table public.quality_audit_checklist_items
  add column if not exists result text check (result is null or result in ('yes', 'partial', 'no', 'na')),
  add column if not exists template_question_id uuid references public.quality_audit_template_questions(id) on delete set null,
  add column if not exists chapter_ref text,
  add column if not exists chapter_title text,
  add column if not exists clause_ref text,
  add column if not exists guidance text,
  add column if not exists evidence_required text,
  add column if not exists evidence text,
  add column if not exists weight numeric(5,2) not null default 1 check (weight > 0),
  add column if not exists critical boolean not null default false,
  add column if not exists finding_class text check (finding_class is null or finding_class in ('major', 'minor', 'observation', 'opportunity')),
  add column if not exists ad_hoc boolean not null default false;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'quality_audit_checklist_items_id_organization_key') then
    alter table public.quality_audit_checklist_items add constraint quality_audit_checklist_items_id_organization_key unique (id, organization_id);
  end if;
end
$$;
create index if not exists quality_audit_checklist_items_question_idx on public.quality_audit_checklist_items (template_question_id);
comment on column public.quality_audit_checklist_items.result is 'The answer on four values: yes = Συμμορφώνεται, partial = Μερική συμμόρφωση, no = Μη συμμόρφωση, na = Δεν εφαρμόζεται. answer keeps the three-value checklist answer (yes / no / na; none for partial) for earlier readers.';
comment on column public.quality_audits.audit_kind is 'internal, external, certification or supplier audit; audit_type stays internal / external (certification and supplier audits are external).';

-- D. Findings -------------------------------------------------------------------------------

alter table public.quality_findings
  add column if not exists finding_class text check (finding_class is null or finding_class in ('major', 'minor', 'observation', 'opportunity')),
  add column if not exists audit_item_id uuid,
  add column if not exists clause_ref text,
  add column if not exists standard text check (standard is null or standard in ('iso9001', 'iso15224', 'haccp', 'iso15189', 'temos', 'jci', 'other')),
  add column if not exists due_date date,
  add column if not exists verification_status text not null default 'pending' check (verification_status in ('pending', 'effective', 'not_effective')),
  add column if not exists verified_on date,
  add column if not exists verified_by_label text,
  add column if not exists verification_note text,
  add column if not exists follow_up_audit_id uuid;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'quality_findings_audit_item_fkey') then
    alter table public.quality_findings add constraint quality_findings_audit_item_fkey
      foreign key (audit_item_id, organization_id) references public.quality_audit_checklist_items(id, organization_id) on delete set null (audit_item_id);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'quality_findings_follow_up_audit_fkey') then
    alter table public.quality_findings add constraint quality_findings_follow_up_audit_fkey
      foreign key (follow_up_audit_id, organization_id) references public.quality_audits(id, organization_id) on delete set null (follow_up_audit_id);
  end if;
end
$$;
create index if not exists quality_findings_audit_item_idx on public.quality_findings (audit_item_id, organization_id);
create index if not exists quality_findings_follow_up_idx on public.quality_findings (follow_up_audit_id, organization_id);
create index if not exists quality_findings_class_idx on public.quality_findings (organization_id, finding_class) where finding_class is not null;

-- Row-level security, grants and audit fields --------------------------------------------------

alter table public.quality_audit_templates enable row level security;
alter table public.quality_audit_template_questions enable row level security;
alter table public.quality_audit_team_members enable row level security;

create policy quality_audit_templates_read on public.quality_audit_templates for select to authenticated using (
  is_system
  or (select public.current_user_is_platform_owner())
  or organization_id = any ((select private.current_user_quality_read_orgs())::uuid[]));
create policy quality_audit_templates_insert on public.quality_audit_templates for insert to authenticated with check (
  (is_system and organization_id is null and (select public.current_user_is_platform_owner()))
  or (not is_system and organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[])));
create policy quality_audit_templates_update on public.quality_audit_templates for update to authenticated
  using ((is_system and (select public.current_user_is_platform_owner())) or (not is_system and organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[])))
  with check ((is_system and organization_id is null and (select public.current_user_is_platform_owner())) or (not is_system and organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[])));
create policy quality_audit_templates_delete on public.quality_audit_templates for delete to authenticated
  using ((is_system and (select public.current_user_is_platform_owner())) or (not is_system and organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[])));

-- A question without an organization is a platform question: only the Platform
-- Owner writes one; every signed-in user reads it with its questionnaire.
create policy quality_audit_template_questions_read on public.quality_audit_template_questions for select to authenticated using (
  organization_id is null
  or (select public.current_user_is_platform_owner())
  or organization_id = any ((select private.current_user_quality_read_orgs())::uuid[]));
create policy quality_audit_template_questions_insert on public.quality_audit_template_questions for insert to authenticated with check (
  (organization_id is null and (select public.current_user_is_platform_owner()))
  or organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[]));
create policy quality_audit_template_questions_update on public.quality_audit_template_questions for update to authenticated
  using ((organization_id is null and (select public.current_user_is_platform_owner())) or organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[]))
  with check ((organization_id is null and (select public.current_user_is_platform_owner())) or organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[]));
create policy quality_audit_template_questions_delete on public.quality_audit_template_questions for delete to authenticated
  using ((organization_id is null and (select public.current_user_is_platform_owner())) or organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[]));

-- The team: read by Quality or whoever reads the audit; written by Quality.
create policy quality_audit_team_members_read on public.quality_audit_team_members for select to authenticated using (
  (select public.current_user_is_platform_owner())
  or organization_id = any ((select private.current_user_quality_read_orgs())::uuid[])
  or exists (select 1 from public.quality_audits p where p.id = audit_id));
create policy quality_audit_team_members_insert on public.quality_audit_team_members for insert to authenticated
  with check ((select public.current_user_is_platform_owner()) or organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[]));
create policy quality_audit_team_members_update on public.quality_audit_team_members for update to authenticated
  using ((select public.current_user_is_platform_owner()) or organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[]))
  with check ((select public.current_user_is_platform_owner()) or organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[]));
create policy quality_audit_team_members_delete on public.quality_audit_team_members for delete to authenticated
  using ((select public.current_user_is_platform_owner()) or organization_id = any ((select private.current_user_quality_manage_orgs())::uuid[]));

do $$
declare t text;
begin
  foreach t in array array['quality_audit_templates', 'quality_audit_template_questions', 'quality_audit_team_members'] loop
    execute format('revoke all on public.%I from anon', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    if not exists (select 1 from pg_trigger where tgrelid = format('public.%I', t)::regclass and tgname = 'trg_' || t || '_audit_fields') then
      execute format('create trigger %I before insert or update on public.%I for each row execute function public.set_repository_audit_fields()', 'trg_' || t || '_audit_fields', t);
    end if;
  end loop;
end
$$;

comment on table public.quality_audit_templates is 'Audit questionnaires: the platform library (is_system, no organization) and each hospital''s own copies (based_on). An audit aid; not the text of a standard.';
comment on table public.quality_audit_template_questions is 'The questions of an audit questionnaire, by chapter and clause, with guidance, evidence, weight, critical flag and the areas they apply to.';
comment on table public.quality_audit_team_members is 'The audit team: employees, or external auditors by name, each with a role (lead, member, expert, observer).';
comment on column public.quality_audits.planned_month_only is 'The audit is planned for the month of planned_date; the day is not fixed yet.';
comment on column public.quality_audits.clauses_scope is 'Chapters or clauses of the questionnaire in scope; empty = all.';
comment on column public.quality_findings.finding_class is 'Audit finding class: major, minor, observation, opportunity (for improvement).';

-- E. The seed: the platform library, one statement per questionnaire. The
-- questions are positioned in the order of their chapters.

with s as (select '{"k":"iso9001","s":"iso9001","v":"2015","t":"ISO 9001:2015 — Σύστημα διαχείρισης ποιότητας","sc":"Όλα τα τμήματα και οι διεργασίες του οργανισμού· οι ερωτήσεις Διοίκησης ελέγχονται στην επιθεώρηση της Διοίκησης / Ποιότητας.","dt":[],"ch":[{"r":"4","t":"Πλαίσιο του οργανισμού","q":[["4.1","Έχει ο οργανισμός καταγράψει τα εσωτερικά και εξωτερικά ζητήματα που επηρεάζουν τον σκοπό και τα αποτελέσματα του συστήματος ποιότητας, και τα επανεξετάζει;","Ανάλυση πλαισίου (π.χ. SWOT / PESTLE), πρακτικά ανασκόπησης","Δείτε πότε επικαιροποιήθηκε τελευταία φορά και αν αξιοποιείται στην ανάλυση κινδύνων.",1,false,["management"]],["4.2","Έχουν προσδιοριστεί τα ενδιαφερόμενα μέρη (ασθενείς, συνοδοί, ταμεία, αρχές, προσωπικό) και οι απαιτήσεις τους που αφορούν το σύστημα;","Μητρώο ενδιαφερόμενων μερών με απαιτήσεις","Ελέγξτε αν περιλαμβάνονται νομοθετικές και κανονιστικές απαιτήσεις.",1,false,["management"]],["4.3","Είναι τεκμηριωμένο και διαθέσιμο το πεδίο εφαρμογής του συστήματος, με αιτιολόγηση για όποια απαίτηση δεν εφαρμόζεται;","Εγχειρίδιο / δήλωση πεδίου, αιτιολόγηση εξαιρέσεων","",1,false,["management"]],["4.4","Έχουν οριστεί οι διεργασίες του τμήματος, οι είσοδοι και έξοδοί τους, η αλληλουχία τους και οι υπεύθυνοί τους;","Χάρτης διεργασιών, διαγράμματα ροής, κάρτες διεργασιών","Ρωτήστε τον υπεύθυνο του τμήματος να περιγράψει τη βασική του διεργασία.",1,false,[]],["4.4.1","Παρακολουθούνται οι διεργασίες με δείκτες και κριτήρια ώστε να φαίνεται αν πετυχαίνουν τα αναμενόμενα αποτελέσματα;","Δείκτες διεργασιών με στόχους και πρόσφατες μετρήσεις","",1,false,[]],["4.4.2","Τηρούνται οι πληροφορίες που χρειάζονται για να υποστηριχθεί η λειτουργία των διεργασιών και να φαίνεται ότι εκτελέστηκαν όπως σχεδιάστηκαν;","Διαδικασίες, οδηγίες εργασίας, αρχεία εκτέλεσης","",1,false,[]]]},{"r":"5","t":"Ηγεσία","q":[["5.1.1","Αναλαμβάνει η Διοίκηση ενεργά την ευθύνη για την αποτελεσματικότητα του συστήματος ποιότητας και το ενσωματώνει στις επιχειρησιακές διεργασίες;","Πρακτικά Διοίκησης, αποφάσεις, παρουσία σε ανασκοπήσεις","Συνέντευξη με μέλος της Διοίκησης.",2,true,["management"]],["5.1.1","Διασφαλίζει η Διοίκηση ότι διατίθενται οι πόροι που χρειάζεται το σύστημα;","Προϋπολογισμός ποιότητας, εγκρίσεις πόρων","",1,false,["management"]],["5.1.2","Είναι η εστίαση στον ασθενή ορατή: προσδιορίζονται οι απαιτήσεις του, αξιολογούνται οι κίνδυνοι που επηρεάζουν την ικανοποίησή του και παρακολουθείται;","Έρευνες ικανοποίησης, ανάλυση παραπόνων","",1,false,[]],["5.2.1","Υπάρχει εγκεκριμένη πολιτική ποιότητας που ταιριάζει στον σκοπό του οργανισμού και δεσμεύεται για συνεχή βελτίωση;","Πολιτική ποιότητας υπογεγραμμένη, με ημερομηνία","",1,false,["management"]],["5.2.2","Γνωρίζει το προσωπικό του τμήματος την πολιτική ποιότητας και πώς η δουλειά του συμβάλλει σε αυτή;","Συνεντεύξεις προσωπικού, ανάρτηση πολιτικής","Ρωτήστε 2–3 εργαζόμενους διαφορετικών ειδικοτήτων.",1,false,[]],["5.3","Είναι σαφώς ορισμένα και γνωστά τα καθήκοντα, οι αρμοδιότητες και οι εξουσίες στο τμήμα;","Οργανόγραμμα, περιγραφές θέσεων, αναθέσεις","",1,true,[]],["5.3","Έχει οριστεί ποιος αναφέρει στη Διοίκηση την απόδοση του συστήματος και τις ευκαιρίες βελτίωσης;","Ορισμός Υπευθύνου Ποιότητας, αναφορές προς Διοίκηση","",1,false,["management"]]]},{"r":"6","t":"Σχεδιασμός","q":[["6.1.1","Έχουν εντοπιστεί οι κίνδυνοι και οι ευκαιρίες του τμήματος που μπορεί να επηρεάσουν την ποιότητα των υπηρεσιών;","Μητρώο κινδύνων τμήματος, εκτίμηση κινδύνου","",2,true,[]],["6.1.2","Έχουν σχεδιαστεί ενέργειες για τους σημαντικούς κινδύνους και αξιολογείται αν ήταν αποτελεσματικές;","Σχέδιο αντιμετώπισης κινδύνων, παρακολούθηση ενεργειών","",1,false,[]],["6.2.1","Υπάρχουν μετρήσιμοι στόχοι ποιότητας για το τμήμα, συνδεδεμένοι με την πολιτική;","Στόχοι ποιότητας με τιμή-στόχο και περίοδο","",1,false,[]],["6.2.2","Για κάθε στόχο έχει οριστεί τι θα γίνει, με ποιους πόρους, ποιος είναι υπεύθυνος, πότε ολοκληρώνεται και πώς θα αξιολογηθεί;","Πλάνα δράσης στόχων, μετρήσεις προόδου","",1,false,[]],["6.3","Οι αλλαγές στο σύστημα ή στις διεργασίες σχεδιάζονται ελεγχόμενα, λαμβάνοντας υπόψη τον σκοπό, τις συνέπειες και τους πόρους;","Αρχείο διαχείρισης αλλαγών, ανάλυση επιπτώσεων","Πάρτε ως παράδειγμα την πιο πρόσφατη αλλαγή διαδικασίας.",1,false,[]]]},{"r":"7","t":"Υποστήριξη","q":[["7.1.2","Επαρκεί το προσωπικό του τμήματος σε αριθμό και ειδικότητες για την ασφαλή λειτουργία του;","Προγράμματα βαρδιών, αναλογίες προσωπικού / ασθενών","",1,false,[]],["7.1.3","Διαθέτει το τμήμα τις υποδομές (χώροι, συστήματα, πληροφορική) που χρειάζεται και συντηρούνται;","Πρόγραμμα συντήρησης, αιτήματα τεχνικής υπηρεσίας","",1,false,[]],["7.1.4","Είναι κατάλληλο το περιβάλλον εργασίας (θερμοκρασία, καθαριότητα, φωτισμός, ψυχοκοινωνικοί παράγοντες);","Μετρήσεις περιβάλλοντος, ελέγχοι καθαριότητας, έρευνα προσωπικού","",1,false,[]],["7.1.5","Ο εξοπλισμός μέτρησης (θερμόμετρα, ζυγοί, πιεσόμετρα, αναλυτές) είναι διακριβωμένος, σημασμένος και προστατευμένος από απορρύθμιση;","Μητρώο εξοπλισμού, πιστοποιητικά διακρίβωσης, ετικέτες","Επιλέξτε 3 όργανα στο τμήμα και ελέγξτε την ετικέτα και το πιστοποιητικό.",2,true,[]],["7.1.5","Όταν ένα όργανο βρεθεί εκτός ορίων διακρίβωσης, αξιολογείται αν επηρεάστηκαν προηγούμενες μετρήσεις και τι ενέργεια χρειάζεται;","Αρχείο αποκλίσεων διακρίβωσης, αξιολογήσεις επίπτωσης","",1,false,[]],["7.1.6","Καταγράφεται και μοιράζεται η γνώση του οργανισμού (διδάγματα από συμβάντα, εμπειρία, εξωτερικές πηγές);","Βάση γνώσης, ενημερωτικά, πρακτικά συναντήσεων","",1,false,[]],["7.2","Έχει οριστεί η απαιτούμενη επάρκεια για κάθε θέση και υπάρχουν τεκμήρια ότι το προσωπικό την έχει;","Περιγραφές θέσεων, πτυχία, άδειες άσκησης, αξιολογήσεις επάρκειας","",2,true,[]],["7.2","Υλοποιείται το πρόγραμμα εκπαίδευσης και αξιολογείται η αποτελεσματικότητα των εκπαιδεύσεων;","Ετήσιο πλάνο εκπαίδευσης, παρουσιολόγια, αξιολογήσεις","",1,false,[]],["7.2","Λαμβάνει το νέο προσωπικό εισαγωγική εκπαίδευση πριν εργαστεί αυτόνομα;","Πρόγραμμα εισαγωγικής εκπαίδευσης, υπογεγραμμένα έντυπα","",1,false,[]],["7.3","Γνωρίζει το προσωπικό τους στόχους ποιότητας του τμήματος και τις συνέπειες μιας μη συμμόρφωσης;","Συνεντεύξεις, ενημερώσεις","",1,false,[]],["7.4","Έχει καθοριστεί τι, πότε, σε ποιον και πώς επικοινωνείται εσωτερικά και εξωτερικά;","Πλάνο επικοινωνίας, ενημερωτικά σημειώματα, πρακτικά","",1,false,[]],["7.4","Τηρούνται πρακτικά από τις συναντήσεις του τμήματος, με αποφάσεις και υπεύθυνους;","Πρακτικά ενδοτμηματικών συναντήσεων","",1,false,[]],["7.5.1","Τηρούνται συστηματικά τα αρχεία που προβλέπει το σύστημα, πλήρη, ευανάγνωστα και χρονολογημένα;","Δειγματοληψία αρχείων (καταγραφές, έντυπα, μητρώα)","",1,false,[]],["7.5.2","Τα έγγραφα του τμήματος έχουν τίτλο, κωδικό, έκδοση, ημερομηνία και έγκριση πριν από τη χρήση;","Λίστα ελεγχόμενων εγγράφων, δείγμα εγγράφων","",1,false,[]],["7.5.3","Στα σημεία χρήσης βρίσκονται μόνο οι ισχύουσες εκδόσεις των εγγράφων και αποσύρονται οι παλιές;","Δειγματοληψία εντύπων στο σημείο εργασίας","Συγκρίνετε την έκδοση ενός εντύπου στο τμήμα με τη λίστα εγγράφων.",1,true,[]],["7.5.3","Προστατεύονται οι ευαίσθητες και εμπιστευτικές πληροφορίες (πρόσβαση, αντίγραφα ασφαλείας, χρόνος διατήρησης);","Δικαιώματα πρόσβασης, πολιτική διατήρησης αρχείων, έλεγχος οθονών","",1,false,[]]]},{"r":"8","t":"Λειτουργία","q":[["8.1","Εκτελούνται οι εργασίες σύμφωνα με τις εγκεκριμένες διαδικασίες και πολιτικές του οργανισμού;","Παρατήρηση εργασίας, σύγκριση με διαδικασία","Ακολουθήστε μία εργασία από την αρχή ως το τέλος.",2,true,[]],["8.1","Έχουν καθοριστεί κριτήρια αποδοχής για τις υπηρεσίες του τμήματος και ελέγχεται η τήρησή τους;","Κριτήρια ποιότητας, αρχεία ελέγχων","",1,false,[]],["8.2.1","Λαμβάνουν οι ασθενείς σαφή πληροφόρηση για τις υπηρεσίες, το κόστος, τα δικαιώματά τους και τον τρόπο υποβολής παραπόνων;","Ενημερωτικά φυλλάδια, ιστοσελίδα, έντυπα συγκατάθεσης","",1,false,[]],["8.2.2","Πριν από την ανάληψη μιας υπηρεσίας επιβεβαιώνεται ότι ο οργανισμός μπορεί να ανταποκριθεί στις απαιτήσεις (ικανότητα, προσωπικό, εξοπλισμός);","Κριτήρια εισαγωγής, ανασκόπηση συμβάσεων","",1,false,[]],["8.2.3","Ανασκοπούνται οι απαιτήσεις πριν από τη δέσμευση (π.χ. προγραμματισμένη εισαγωγή, σύμβαση με ασφαλιστικό φορέα) και λύνονται οι διαφορές;","Αρχεία ανασκόπησης, εγκρίσεις","",1,false,[]],["8.2.4","Όταν αλλάζουν οι απαιτήσεις μιας υπηρεσίας, ενημερώνονται τα σχετικά έγγραφα και τα εμπλεκόμενα πρόσωπα;","Τροποποιήσεις συμβάσεων, ενημερώσεις","",1,false,[]],["8.3","Όταν σχεδιάζεται νέα υπηρεσία ή κλινική διαδρομή, υπάρχουν στάδια σχεδιασμού, ανασκόπησης, επαλήθευσης και επικύρωσης;","Φάκελος σχεδιασμού, πρακτικά επικύρωσης","",1,false,["management"]],["8.4.1","Αξιολογούνται και επαναξιολογούνται οι εξωτερικοί πάροχοι με καθορισμένα κριτήρια;","Λίστα εγκεκριμένων προμηθευτών, αξιολογήσεις","",1,false,[]],["8.4.2","Ελέγχονται κατά την παραλαβή τα προϊόντα και οι υπηρεσίες που προμηθεύεται το τμήμα;","Δελτία παραλαβής, αρχεία ελέγχου παραλαβής","",1,false,[]],["8.4.2","Παρακολουθείται η απόδοση των υπεργολάβων που εργάζονται μέσα στο νοσοκομείο (καθαριότητα, εστίαση, συντήρηση);","Έλεγχοι υπεργολάβων, πρακτικά επικοινωνίας","",1,false,[]],["8.4.3","Γνωστοποιούνται με σαφήνεια στους προμηθευτές οι απαιτήσεις (προδιαγραφές, πιστοποιήσεις, χρόνοι);","Παραγγελίες, συμβάσεις, τεχνικές προδιαγραφές","",1,false,[]],["8.5.1","Παρέχονται οι υπηρεσίες υπό ελεγχόμενες συνθήκες: διαθέσιμες οδηγίες, κατάλληλος εξοπλισμός, ικανό προσωπικό και έλεγχοι στα κρίσιμα σημεία;","Οδηγίες εργασίας στο σημείο, αρχεία ελέγχων","",1,false,[]],["8.5.1","Επικυρώνονται οι διεργασίες των οποίων το αποτέλεσμα δεν ελέγχεται εκ των υστέρων (π.χ. αποστείρωση, παρασκευή φαρμάκων);","Πρωτόκολλα επικύρωσης, επανεπικυρώσεις","",1,true,[]],["8.5.1","Εφαρμόζονται μέτρα για την πρόληψη του ανθρώπινου λάθους (διπλός έλεγχος, λίστες ελέγχου, σήμανση);","Λίστες ελέγχου, διπλές υπογραφές","",1,false,[]],["8.5.2","Εξασφαλίζεται η ταυτοποίηση και η ιχνηλασιμότητα (ασθενής, δείγμα, παρτίδα υλικού, φάρμακο) όπου απαιτείται;","Βραχιόλια ταυτοποίησης, ετικέτες, αρχεία παρτίδων","",2,true,[]],["8.5.3","Προστατεύεται η περιουσία των ασθενών (προσωπικά αντικείμενα, δεδομένα, δείγματα);","Διαδικασία φύλαξης, αρχεία παραλαβής-παράδοσης","",1,false,[]],["8.5.4","Διατηρούνται σωστά τα υλικά και φάρμακα (συνθήκες φύλαξης, λήξεις, συσκευασία);","Έλεγχος αποθήκης τμήματος, καταγραφές θερμοκρασίας","Ελέγξτε 5 τυχαία υλικά για ημερομηνία λήξης.",1,false,[]],["8.5.5","Καλύπτονται οι δραστηριότητες μετά την παροχή υπηρεσίας (οδηγίες εξόδου, επανεπισκέψεις, παρακολούθηση);","Οδηγίες εξόδου, προγραμματισμός παρακολούθησης","",1,false,[]],["8.5.6","Οι αλλαγές στην παροχή υπηρεσιών ελέγχονται και καταγράφονται με το ποιος τις ενέκρινε;","Αρχεία αλλαγών, εγκρίσεις","",1,false,[]],["8.6","Επαληθεύεται ότι πληρούνται οι απαιτήσεις πριν από την αποδέσμευση μιας υπηρεσίας ή ενός αποτελέσματος, και καταγράφεται ποιος την ενέκρινε;","Υπογραφές έγκρισης, αρχεία ελέγχου πριν την αποδέσμευση","",1,false,[]],["8.7","Οι μη συμμορφώσεις (υλικό, υπηρεσία, αποτέλεσμα) εντοπίζονται, σημαίνονται και διαχειρίζονται ώστε να μη χρησιμοποιηθούν κατά λάθος;","Αρχείο μη συμμορφώσεων, χώρος καραντίνας υλικών","",1,true,[]],["8.7","Γνωρίζει το προσωπικό τις διαδικασίες έκτακτων καταστάσεων και κρίσεων (πυρκαγιά, διακοπή ρεύματος, μαζικά συμβάντα);","Σχέδια έκτακτης ανάγκης, ασκήσεις ετοιμότητας, συνεντεύξεις","",1,false,[]]]},{"r":"9","t":"Αξιολόγηση της απόδοσης","q":[["9.1.1","Έχει καθοριστεί τι μετράται, πώς, πότε και πότε αναλύονται τα αποτελέσματα;","Πλάνο δεικτών, μητρώα δεικτών, αναφορές","",1,false,[]],["9.1.1","Διενεργούνται και καταγράφονται οι προγραμματισμένοι έλεγχοι του τμήματος;","Πρόγραμμα ελέγχων, αρχεία εκτέλεσης","",1,false,[]],["9.1.2","Παρακολουθείται η ικανοποίηση των ασθενών και αξιοποιούνται τα αποτελέσματα;","Έρευνες ικανοποίησης, σχέδια βελτίωσης","",1,false,[]],["9.1.2","Απαντώνται τα παράπονα εντός της προθεσμίας και ενημερώνεται ο ασθενής για το αποτέλεσμα;","Μητρώο παραπόνων με ημερομηνίες απάντησης","",1,false,[]],["9.1.3","Αναλύονται τα δεδομένα (δείκτες, ελέγχοι, παράπονα, συμβάντα) και τα συμπεράσματα οδηγούν σε ενέργειες;","Αναφορές ανάλυσης, τάσεις, πρακτικά","",1,false,[]],["9.1.3","Αξιολογείται η απόδοση των εξωτερικών παρόχων με βάση τα δεδομένα (καθυστερήσεις, μη συμμορφώσεις);","Αξιολογήσεις προμηθευτών","",1,false,[]],["9.2.1","Γίνονται εσωτερικές επιθεωρήσεις σε προγραμματισμένα διαστήματα για να φανεί αν το σύστημα συμμορφώνεται και εφαρμόζεται αποτελεσματικά;","Ετήσιο πρόγραμμα επιθεωρήσεων, εκθέσεις","",1,false,["management"]],["9.2.2","Το πρόγραμμα επιθεωρήσεων λαμβάνει υπόψη τη σημασία των διεργασιών, τις αλλαγές και τα αποτελέσματα προηγούμενων επιθεωρήσεων;","Πρόγραμμα με αιτιολόγηση συχνότητας","",1,false,["management"]],["9.2.2","Οι επιθεωρητές είναι ανεξάρτητοι από το αντικείμενο που επιθεωρούν και έχουν την απαιτούμενη επάρκεια;","Ανάθεση επιθεωρητών, εκπαίδευση επιθεωρητών","",1,true,["management"]],["9.2.2","Τα αποτελέσματα των επιθεωρήσεων αναφέρονται στη Διοίκηση και οι διορθώσεις γίνονται χωρίς αδικαιολόγητη καθυστέρηση;","Εκθέσεις, παρακολούθηση ευρημάτων","",1,false,[]],["9.2.2","Τηρούνται τα αρχεία του προγράμματος και των αποτελεσμάτων κάθε επιθεώρησης;","Φάκελος επιθεωρήσεων","",1,false,["management"]],["9.3.1","Ανασκοπεί η Διοίκηση το σύστημα σε προγραμματισμένα διαστήματα;","Πρακτικά ανασκόπησης διοίκησης","",2,true,["management"]],["9.3.2","Η ανασκόπηση εξετάζει όλα τα απαιτούμενα θέματα: προηγούμενες αποφάσεις, αλλαγές, ικανοποίηση, στόχους, μη συμμορφώσεις, επιθεωρήσεις, προμηθευτές, πόρους, κινδύνους;","Ατζέντα και πρακτικά ανασκόπησης","",1,false,["management"]],["9.3.3","Οι αποφάσεις της ανασκόπησης έχουν υπεύθυνους και προθεσμίες και παρακολουθούνται;","Λίστα αποφάσεων με κατάσταση","",1,false,["management"]]]},{"r":"10","t":"Βελτίωση","q":[["10.1","Εντοπίζονται και υλοποιούνται ευκαιρίες βελτίωσης στο τμήμα;","Προτάσεις βελτίωσης, έργα βελτίωσης","",1,false,[]],["10.2.1","Καταγράφονται τα συμβάντα και οι μη συμμορφώσεις σύμφωνα με τη διαδικασία;","Αρχείο αναφορών συμβάντων, έντυπα","",2,true,[]],["10.2.1","Για κάθε σημαντική μη συμμόρφωση αναλύεται η ριζική αιτία και λαμβάνεται διορθωτική ενέργεια;","Αναλύσεις ριζικής αιτίας, σχέδια CAPA","",1,false,[]],["10.2.1","Επαληθεύεται η αποτελεσματικότητα των διορθωτικών ενεργειών πριν κλείσουν;","Αρχεία επαλήθευσης αποτελεσματικότητας","",1,false,[]],["10.2.1","Επικαιροποιούνται οι κίνδυνοι και οι ευκαιρίες όταν μια μη συμμόρφωση το απαιτεί;","Ενημερωμένο μητρώο κινδύνων","",1,false,[]],["10.2.2","Τηρούνται αρχεία για τη φύση των μη συμμορφώσεων, τις ενέργειες και τα αποτελέσματά τους;","Μητρώο μη συμμορφώσεων και CAPA","",1,false,[]],["10.3","Αξιοποιούνται τα αποτελέσματα ανάλυσης και ανασκόπησης για τη συνεχή βελτίωση του συστήματος;","Σχέδιο βελτίωσης, σύγκριση δεικτών με το προηγούμενο έτος","",1,false,["management"]]]}]}'::jsonb j),
tp as (insert into public.quality_audit_templates (organization_id, is_system, template_key, standard, standard_version, title, description, scope, department_types, active, version, source)
 select null, true, j->>'k', j->>'s', j->>'v', j->>'t', 'Βοήθημα επιθεώρησης για το ' || (j->>'t') || ': ερωτήσεις διατυπωμένες με δικά μας λόγια, με αναφορά στο άρθρο ή το κεφάλαιο. Δεν αποτελεί το κείμενο του προτύπου, που παραμένει η πηγή αναφοράς. Επεξεργάσιμο: δημιουργήστε αντίγραφο για το νοσοκομείο σας και προσαρμόστε το.', j->>'sc', array(select jsonb_array_elements_text(j->'dt')), true, 1, 'seed' from s
 on conflict on constraint quality_audit_templates_title_key do nothing returning id),
qs as (select ch.value->>'r' r, ch.value->>'t' t, q.value v, row_number() over (order by ch.ordinality, q.ordinality) p
 from s, jsonb_array_elements(j->'ch') with ordinality ch, jsonb_array_elements(ch.value->'q') with ordinality q)
insert into public.quality_audit_template_questions (template_id, organization_id, position, chapter_ref, chapter_title, clause_ref, question, guidance, evidence, weight, critical, areas)
select tp.id, null, qs.p, qs.r, qs.t, qs.v->>0, qs.v->>1, nullif(qs.v->>3, ''), nullif(qs.v->>2, ''), (qs.v->>4)::numeric, (qs.v->>5)::boolean, array(select jsonb_array_elements_text(qs.v->6)) from tp, qs;

with s as (select '{"k":"iso15224","s":"iso15224","v":"2016","t":"ISO 15224 — Διαχείριση ποιότητας στις υπηρεσίες υγείας","sc":"Κλινικές διεργασίες και υποστηρικτικές υπηρεσίες· οι 11 ποιοτικές παράμετροι της φροντίδας υγείας και η διαχείριση κλινικού κινδύνου.","dt":["clinical","management"],"ch":[{"r":"4","t":"Πλαίσιο και κλινικές διεργασίες","q":[["4.1","Λαμβάνει υπόψη η ανάλυση πλαισίου τις ανάγκες υγείας του πληθυσμού που εξυπηρετεί ο οργανισμός και τις επαγγελματικές και κανονιστικές απαιτήσεις;","Ανάλυση πλαισίου, επιδημιολογικά στοιχεία περιοχής","",1,false,["management"]],["4.4","Είναι χαρτογραφημένες οι κλινικές διεργασίες του τμήματος (από την εισαγωγή ως την έξοδο ή τη μεταφορά) με τα σημεία κλινικού κινδύνου;","Κλινικές διαδρομές, διαγράμματα ροής ασθενούς","",2,true,[]],["4.4","Έχει κάθε κλινική διεργασία υπεύθυνο και δείκτες για την ποιότητα και την ασφάλεια;","Κάρτες διεργασίας, δείκτες","",1,false,[]]]},{"r":"5","t":"Ηγεσία και κλινική διακυβέρνηση","q":[["5.1","Δεσμεύεται η Διοίκηση για την ασφάλεια των ασθενών και την καλλιέργεια κουλτούρας αναφοράς χωρίς τιμωρία;","Πολιτική ασφάλειας ασθενών, μηνύματα Διοίκησης","",1,true,["management"]],["5.3","Είναι σαφείς οι κλινικές ευθύνες (ποιος είναι υπεύθυνος για κάθε ασθενή σε κάθε βάρδια);","Πίνακας υπευθύνων ιατρών/νοσηλευτών, προγράμματα εφημεριών","",1,true,[]],["5.3","Συμμετέχουν οι κλινικοί επαγγελματίες στη διακυβέρνηση της ποιότητας (επιτροπές, κλινικοί υπεύθυνοι ποιότητας);","Σύνθεση επιτροπών, πρακτικά","",1,false,["management"]]]},{"r":"6","t":"Διαχείριση κλινικού κινδύνου","q":[["6.1","Εκτιμώνται συστηματικά οι κλινικοί κίνδυνοι του τμήματος (πτώσεις, λοιμώξεις, λάθη φαρμάκων, κατακλίσεις, ταυτοποίηση);","Μητρώο κλινικών κινδύνων, εργαλείο εκτίμησης","",2,true,[]],["6.1","Γίνεται εκτίμηση κινδύνου ανά ασθενή κατά την εισαγωγή (π.χ. πτώσεις, κατακλίσεις, θρομβοεμβολή) και επανεκτίμηση όταν αλλάζει η κατάσταση;","Κλίμακες εκτίμησης στον φάκελο ασθενούς","Ελέγξτε 5 φακέλους νοσηλευόμενων.",1,false,["clinical"]],["6.1","Αναλύονται προληπτικά οι διεργασίες υψηλού κινδύνου (π.χ. FMEA) πριν από αλλαγές;","Αναλύσεις FMEA, σχέδια μείωσης κινδύνου","",1,false,[]],["6.2","Περιλαμβάνουν οι στόχοι ποιότητας κλινικά αποτελέσματα και δείκτες ασφάλειας ασθενών;","Στόχοι με κλινικούς δείκτες","",1,false,[]]]},{"r":"7","t":"Υποστήριξη της φροντίδας","q":[["7.1.2","Σχεδιάζεται η στελέχωση με βάση τον φόρτο και τη βαρύτητα των ασθενών;","Εργαλείο υπολογισμού στελέχωσης, προγράμματα","",1,false,[]],["7.1.5","Ελέγχεται η αξιοπιστία του ιατροτεχνολογικού εξοπλισμού (συντήρηση, έλεγχοι ασφαλείας, ανακλήσεις κατασκευαστή);","Μητρώο εξοπλισμού, αρχεία συντήρησης, ειδοποιήσεις ασφαλείας","",1,true,[]],["7.2","Επαληθεύεται ότι οι επαγγελματίες υγείας έχουν σε ισχύ άδεια άσκησης και τα προνόμια για όσα εκτελούν;","Άδειες άσκησης, κλινικά προνόμια","",2,true,[]],["7.2","Εκπαιδεύεται το προσωπικό στην ασφάλεια ασθενών και στην αναφορά συμβάντων;","Εκπαιδεύσεις ασφάλειας ασθενών, παρουσιολόγια","",1,false,[]],["7.5","Ο ιατρικός φάκελος είναι πλήρης, χρονολογημένος, υπογεγραμμένος και διαθέσιμος σε όσους φροντίζουν τον ασθενή;","Έλεγχος δείγματος φακέλων","Ελέγξτε 5–10 φακέλους με λίστα πληρότητας.",2,true,["clinical"]],["7.5","Προστατεύεται το απόρρητο των δεδομένων υγείας και καταγράφεται η πρόσβαση;","Δικαιώματα πρόσβασης, ίχνη πρόσβασης, συμβάσεις εμπιστευτικότητας","",1,false,[]]]},{"r":"8","t":"Παροχή φροντίδας υγείας","q":[["8.1","Βασίζεται ο σχεδιασμός της φροντίδας σε κατευθυντήριες οδηγίες και πρωτόκολλα που ισχύουν;","Πρωτόκολλα με ημερομηνία αναθεώρησης, παραπομπές","",1,false,["clinical"]],["8.2","Συμφωνείται με τον ασθενή το σχέδιο φροντίδας και λαμβάνεται ενημερωμένη συγκατάθεση πριν από πράξεις;","Έντυπα συγκατάθεσης, σχέδια φροντίδας","",1,true,["clinical"]],["8.4","Ελέγχονται οι εξωτερικές υπηρεσίες που επηρεάζουν την κλινική φροντίδα (εργαστήρια αναφοράς, μεταφορές, απεικονίσεις);","Συμβάσεις, δείκτες απόδοσης παρόχων","",1,false,[]],["8.5.1","Ταυτοποιείται ο ασθενής με δύο στοιχεία πριν από κάθε πράξη, φάρμακο ή αιμοληψία;","Παρατήρηση, βραχιόλια ταυτοποίησης","",2,true,["clinical"]],["8.5.1","Γίνεται δομημένη παράδοση-παραλαβή ασθενών μεταξύ βαρδιών και τμημάτων (π.χ. SBAR);","Έντυπα παράδοσης, παρατήρηση","",1,false,["clinical"]],["8.5.5","Δίνονται στον ασθενή κατά την έξοδο γραπτές οδηγίες, φαρμακευτική αγωγή και σημείο επικοινωνίας;","Σημειώματα εξόδου","",1,false,["clinical"]],["8.7","Αναφέρονται και διερευνώνται τα ανεπιθύμητα συμβάντα και τα «παρ’ ολίγον»;","Μητρώο συμβάντων, διερευνήσεις","",2,true,[]],["8.7","Ενημερώνεται ο ασθενής ή η οικογένεια με ειλικρίνεια όταν συμβεί βλάβη (ανοιχτή γνωστοποίηση);","Πολιτική γνωστοποίησης, αρχεία ενημέρωσης","",1,false,["clinical"]]]},{"r":"9","t":"Μέτρηση κλινικών αποτελεσμάτων","q":[["9.1","Μετρώνται τα κλινικά αποτελέσματα (π.χ. επανεισαγωγές, λοιμώξεις, θνητότητα, επιπλοκές) και συγκρίνονται με στόχους ή αναφορές;","Μητρώα δεικτών, συγκριτικές αναφορές","",1,true,[]],["9.1","Αξιοποιούνται οι εμπειρίες των ασθενών (PREMs) και τα αναφερόμενα αποτελέσματα (PROMs) όπου είναι εφικτό;","Ερωτηματολόγια, αναλύσεις","",1,false,[]],["9.2","Καλύπτει το πρόγραμμα επιθεωρήσεων κλινικές επιθεωρήσεις (clinical audit) με κριτήρια από τις κατευθυντήριες οδηγίες;","Κλινικές επιθεωρήσεις, κύκλοι επανεπιθεώρησης","",1,false,["management"]],["9.3","Εξετάζει η ανασκόπηση της Διοίκησης τα κλινικά αποτελέσματα, τα σοβαρά συμβάντα και τους κλινικούς κινδύνους;","Πρακτικά ανασκόπησης","",1,false,["management"]]]},{"r":"10","t":"Βελτίωση της φροντίδας","q":[["10.2","Γίνεται ανάλυση ριζικής αιτίας στα σοβαρά συμβάντα και μοιράζονται τα διδάγματα με όλα τα τμήματα;","RCA, ενημερωτικά διδαγμάτων","",1,true,[]],["10.3","Υπάρχουν έργα βελτίωσης της ποιότητας με κλινική συμμετοχή και μετρήσιμο αποτέλεσμα;","Έργα βελτίωσης (PDSA), αποτελέσματα","",1,false,[]]]},{"r":"ΧΠ-1","t":"Κατάλληλη, ορθή φροντίδα","q":[["ΧΠ-1","Αντιστοιχούν οι εξετάσεις και οι θεραπείες στις ανάγκες του ασθενή, χωρίς υπερβολή ή παράλειψη;","Έλεγχος φακέλων με κριτήρια καταλληλότητας","",1,false,["clinical"]],["ΧΠ-1","Τεκμηριώνεται η κλινική αιτιολόγηση για αποκλίσεις από τα πρωτόκολλα;","Σημειώσεις στον φάκελο","",1,false,["clinical"]]]},{"r":"ΧΠ-2","t":"Διαθεσιμότητα","q":[["ΧΠ-2","Είναι διαθέσιμες οι απαραίτητες υπηρεσίες, το προσωπικό και ο εξοπλισμός όταν τις χρειάζεται ο ασθενής (και εκτός ωραρίου);","Προγράμματα εφημεριών, διαθεσιμότητα κλινών","",1,false,[]],["ΧΠ-2","Υπάρχουν σχέδια για την κάλυψη ελλείψεων προσωπικού ή βλαβών κρίσιμου εξοπλισμού;","Σχέδια συνέχειας λειτουργίας","",1,false,[]]]},{"r":"ΧΠ-3","t":"Συνέχεια της φροντίδας","q":[["ΧΠ-3","Εξασφαλίζεται η συνέχεια της φροντίδας κατά τις μεταφορές μεταξύ τμημάτων, νοσοκομείων και πρωτοβάθμιας φροντίδας;","Σημειώματα μεταφοράς, επικοινωνία με θεράποντα","",1,true,["clinical"]],["ΧΠ-3","Συμφιλιώνεται η φαρμακευτική αγωγή στην εισαγωγή, στη μεταφορά και στην έξοδο;","Φύλλα συμφιλίωσης φαρμάκων","",1,false,["clinical"]]]},{"r":"ΧΠ-4","t":"Αποτελεσματικότητα","q":[["ΧΠ-4","Παρακολουθείται αν η φροντίδα πετυχαίνει τα επιδιωκόμενα αποτελέσματα υγείας για τον ασθενή;","Δείκτες αποτελέσματος","",1,false,[]],["ΧΠ-4","Αναθεωρούνται τα πρωτόκολλα όταν τα αποτελέσματα δεν είναι τα αναμενόμενα;","Ιστορικό αναθεωρήσεων πρωτοκόλλων","",1,false,[]]]},{"r":"ΧΠ-5","t":"Αποδοτικότητα","q":[["ΧΠ-5","Χρησιμοποιούνται οι πόροι χωρίς σπατάλη (διάρκεια νοσηλείας, επαναλήψεις εξετάσεων, αναλώσιμα);","Δείκτες διάρκειας νοσηλείας, κατανάλωσης","",1,false,[]],["ΧΠ-5","Εντοπίζονται και περιορίζονται οι καθυστερήσεις και οι αναμονές χωρίς προστιθέμενη αξία;","Ανάλυση ροών, χρόνοι αναμονής","",1,false,[]]]},{"r":"ΧΠ-6","t":"Ισότητα","q":[["ΧΠ-6","Παρέχεται ίση φροντίδα ανεξάρτητα από φύλο, ηλικία, καταγωγή, γλώσσα, αναπηρία ή ασφαλιστική κάλυψη;","Πολιτική ισότητας, παράπονα, πρόσβαση ΑμεΑ","",1,false,[]],["ΧΠ-6","Υπάρχει διερμηνεία ή άλλη υποστήριξη για ασθενείς με γλωσσικά ή αισθητηριακά εμπόδια;","Διαδικασία διερμηνείας, αρχεία χρήσης","",1,false,[]]]},{"r":"ΧΠ-7","t":"Τεκμηριωμένη (βασισμένη στη γνώση) φροντίδα","q":[["ΧΠ-7","Στηρίζονται τα κλινικά πρωτόκολλα σε επιστημονικά τεκμήρια με αναφορές και αναθεωρούνται τακτικά;","Πρωτόκολλα με βιβλιογραφία και ημερομηνία","",1,true,[]],["ΧΠ-7","Έχει το προσωπικό πρόσβαση σε επικαιροποιημένες πηγές γνώσης και συνεχιζόμενη εκπαίδευση;","Πρόσβαση σε βάσεις, πρόγραμμα CME","",1,false,[]]]},{"r":"ΧΠ-8","t":"Ασθενοκεντρική φροντίδα και ακεραιότητα","q":[["ΧΠ-8","Γίνονται σεβαστές η αξιοπρέπεια, η ιδιωτικότητα και οι πολιτισμικές ή θρησκευτικές ανάγκες του ασθενή;","Παρατήρηση (παραβάν, συζητήσεις), έρευνες εμπειρίας","",1,false,["clinical"]],["ΧΠ-8","Αξιολογούνται και αντιμετωπίζονται ο πόνος και οι ψυχολογικές και κοινωνικές ανάγκες του ασθενή;","Κλίμακες πόνου, παραπομπές σε ψυχολόγο / κοινωνική υπηρεσία","",1,false,["clinical"]]]},{"r":"ΧΠ-9","t":"Συμμετοχή του ασθενούς","q":[["ΧΠ-9","Συμμετέχει ο ασθενής (και όπου χρειάζεται η οικογένεια) στις αποφάσεις για τη φροντίδα του;","Σχέδια φροντίδας, κοινή λήψη απόφασης","",1,false,["clinical"]],["ΧΠ-9","Ενθαρρύνονται οι ασθενείς να μιλούν για ανησυχίες ασφάλειας και αξιοποιούνται οι προτάσεις τους;","Ενημερωτικό υλικό, κανάλια ανατροφοδότησης","",1,false,[]]]},{"r":"ΧΠ-10","t":"Ασφάλεια ασθενών","q":[["ΧΠ-10","Εφαρμόζονται τα βασικά μέτρα ασφάλειας: ταυτοποίηση, ασφαλής χορήγηση φαρμάκων, υγιεινή χεριών, πρόληψη πτώσεων, χειρουργική λίστα ελέγχου;","Παρατηρήσεις συμμόρφωσης, δείκτες","",2,true,[]],["ΧΠ-10","Είναι ασφαλής η φύλαξη και η χορήγηση των φαρμάκων υψηλού κινδύνου (σήμανση, διπλός έλεγχος);","Επιθεώρηση φαρμακείου τμήματος","",1,true,["clinical"]],["ΧΠ-10","Μετρώνται και μειώνονται οι λοιμώξεις που σχετίζονται με τη φροντίδα;","Επιτήρηση λοιμώξεων, δέσμες μέτρων","",1,false,[]]]},{"r":"ΧΠ-11","t":"Έγκαιρη φροντίδα και προσβασιμότητα","q":[["ΧΠ-11","Παρακολουθούνται οι χρόνοι αναμονής (ΤΕΠ, εξωτερικά ιατρεία, χειρουργεία, αποτελέσματα εξετάσεων) έναντι στόχων;","Δείκτες χρόνων αναμονής","",1,false,[]],["ΧΠ-11","Είναι προσβάσιμοι οι χώροι και οι υπηρεσίες για άτομα με κινητικά ή άλλα προβλήματα;","Έλεγχος χώρων, σήμανση","",1,false,[]],["ΧΠ-11","Κοινοποιούνται έγκαιρα τα κρίσιμα αποτελέσματα στον θεράποντα και τεκμηριώνεται η λήψη;","Αρχείο κρίσιμων τιμών","",1,true,[]]]}]}'::jsonb j),
tp as (insert into public.quality_audit_templates (organization_id, is_system, template_key, standard, standard_version, title, description, scope, department_types, active, version, source)
 select null, true, j->>'k', j->>'s', j->>'v', j->>'t', 'Βοήθημα επιθεώρησης για το ' || (j->>'t') || ': ερωτήσεις διατυπωμένες με δικά μας λόγια, με αναφορά στο άρθρο ή το κεφάλαιο. Δεν αποτελεί το κείμενο του προτύπου, που παραμένει η πηγή αναφοράς. Επεξεργάσιμο: δημιουργήστε αντίγραφο για το νοσοκομείο σας και προσαρμόστε το.', j->>'sc', array(select jsonb_array_elements_text(j->'dt')), true, 1, 'seed' from s
 on conflict on constraint quality_audit_templates_title_key do nothing returning id),
qs as (select ch.value->>'r' r, ch.value->>'t' t, q.value v, row_number() over (order by ch.ordinality, q.ordinality) p
 from s, jsonb_array_elements(j->'ch') with ordinality ch, jsonb_array_elements(ch.value->'q') with ordinality q)
insert into public.quality_audit_template_questions (template_id, organization_id, position, chapter_ref, chapter_title, clause_ref, question, guidance, evidence, weight, critical, areas)
select tp.id, null, qs.p, qs.r, qs.t, qs.v->>0, qs.v->>1, nullif(qs.v->>3, ''), nullif(qs.v->>2, ''), (qs.v->>4)::numeric, (qs.v->>5)::boolean, array(select jsonb_array_elements_text(qs.v->6)) from tp, qs;

with s as (select '{"k":"haccp","s":"haccp","v":"ISO 22000:2018","t":"HACCP / ISO 22000 — Ασφάλεια τροφίμων (κουζίνα)","sc":"Κουζίνα, αποθήκες τροφίμων, διανομή γευμάτων στα τμήματα, εναλλακτικές διατροφές και εντερική σίτιση όπου ετοιμάζεται στην κουζίνα.","dt":["kitchen"],"ch":[{"r":"ΠΠ","t":"Προαπαιτούμενα προγράμματα (PRPs)","q":[["ΠΠ-1","Είναι οι χώροι της κουζίνας σε καλή κατάσταση (δάπεδα, τοίχοι, οροφές, αποχετεύσεις) και καθαρίζονται εύκολα;","Επιθεώρηση χώρων, αιτήματα συντήρησης","",1,false,["kitchen"]],["ΠΠ-1","Είναι η ροή εργασίας μονόδρομη, ώστε να μη διασταυρώνονται ωμά και έτοιμα προς κατανάλωση τρόφιμα;","Κάτοψη, παρατήρηση ροής","",2,true,["kitchen"]],["ΠΠ-2","Είναι πόσιμο το νερό που χρησιμοποιείται και ελέγχεται με αναλύσεις;","Αναλύσεις νερού, πρόγραμμα δειγματοληψιών","",1,false,["kitchen"]],["ΠΠ-3","Διαχειρίζονται τα απορρίμματα σε κλειστούς κάδους, απομακρύνονται τακτικά και δεν μολύνουν τα τρόφιμα;","Παρατήρηση, πρόγραμμα αποκομιδής","",1,false,["kitchen"]],["ΠΠ-4","Είναι ο εξοπλισμός κατάλληλος για τρόφιμα, σε καλή κατάσταση και συντηρείται προληπτικά;","Πρόγραμμα συντήρησης εξοπλισμού","",1,false,["kitchen"]],["ΠΠ-4","Ελέγχονται και διακριβώνονται τα θερμόμετρα (πυρήνα, ψυγείων, καταψυκτών);","Αρχεία ελέγχου θερμομέτρων","",2,true,["kitchen"]],["ΠΠ-5","Προμηθεύεται η κουζίνα πρώτες ύλες μόνο από εγκεκριμένους προμηθευτές που αξιολογούνται;","Λίστα εγκεκριμένων προμηθευτών, αξιολογήσεις (Προμηθευτές Κουζίνας)","",1,false,["kitchen"]],["ΠΠ-5","Ελέγχονται κατά την παραλαβή η θερμοκρασία, η συσκευασία, η επισήμανση και οι λήξεις, με καταγραφή και απόρριψη όπου χρειάζεται;","Έντυπα ελέγχου παραλαβής (Κουζίνα)","",2,true,["kitchen"]],["ΠΠ-6","Λαμβάνονται μέτρα κατά της επιμόλυνσης (χρωματικός κώδικας επιφανειών κοπής, διαχωρισμός ωμών / μαγειρεμένων);","Παρατήρηση, χρωματικός κώδικας","",2,true,["kitchen"]],["ΠΠ-6","Ελέγχονται τα αλλεργιογόνα (επισήμανση, διαχωρισμός, ενημέρωση για τις ειδικές διατροφές των ασθενών);","Κατάλογος αλλεργιογόνων ανά συνταγή, κάρτες διατροφής","",2,true,["kitchen"]],["ΠΠ-7","Εφαρμόζεται γραπτό πρόγραμμα καθαρισμού και απολύμανσης με τα σωστά προϊόντα και συγκεντρώσεις, και καταγράφεται;","Πρόγραμμα καθαριότητας, αρχεία (Κουζίνα)","",1,false,["kitchen"]],["ΠΠ-7","Επαληθεύεται η αποτελεσματικότητα του καθαρισμού (οπτικά, ATP ή μικροβιολογικά επιχρίσματα);","Αποτελέσματα επιχρισμάτων","",1,false,["kitchen"]],["ΠΠ-8","Εφαρμόζεται πρόγραμμα καταπολέμησης τρωκτικών και εντόμων με χάρτη δολωμάτων και αναφορές συνεργείου;","Σύμβαση απεντόμωσης, χάρτης, αναφορές","",1,false,["kitchen"]],["ΠΠ-9","Τηρεί το προσωπικό τους κανόνες ατομικής υγιεινής (ρουχισμός, κάλυμμα κεφαλής, χωρίς κοσμήματα, πλύσιμο χεριών);","Παρατήρηση, σημεία πλυσίματος χεριών","",2,true,["kitchen"]],["ΠΠ-9","Δηλώνει το προσωπικό τα συμπτώματα λοίμωξης και αποκλείεται από τον χειρισμό τροφίμων όταν χρειάζεται;","Διαδικασία αναφοράς υγείας, βιβλιάρια υγείας","",1,false,["kitchen"]],["ΠΠ-9","Είναι εκπαιδευμένο το προσωπικό στην υγιεινή τροφίμων ανάλογα με τη θέση του;","Πιστοποιητικά εκπαίδευσης υγιεινής τροφίμων","",1,false,["kitchen"]],["ΠΠ-10","Αποθηκεύονται τα τρόφιμα σωστά (FIFO / FEFO, από το δάπεδο, ωμά κάτω από τα έτοιμα, σήμανση ανοίγματος);","Επιθεώρηση αποθηκών και ψυγείων","",1,false,["kitchen"]],["ΠΠ-10","Καταγράφονται οι θερμοκρασίες ψυγείων και καταψυκτών τουλάχιστον δύο φορές την ημέρα με ενέργειες σε απόκλιση;","Φύλλα θερμοκρασιών (Κουζίνα)","",2,true,["kitchen"]],["ΠΠ-11","Υπάρχει διαδικασία ανάκλησης / απόσυρσης προϊόντων και δοκιμάζεται;","Διαδικασία ανάκλησης, άσκηση ιχνηλασιμότητας","",1,false,["kitchen"]],["ΠΠ-12","Μεταφέρονται τα γεύματα στα τμήματα σε θερμοκρασίες ασφάλειας (ζεστά ≥ 63 °C, κρύα ≤ 5 °C) και ελέγχεται κατά τη διανομή;","Καταγραφές θερμοκρασίας διανομής","",2,true,["kitchen"]]]},{"r":"ΠΒ","t":"Προκαταρκτικά βήματα HACCP","q":[["ΠΒ-1","Έχει οριστεί ομάδα HACCP / ασφάλειας τροφίμων με τις απαιτούμενες γνώσεις;","Απόφαση ορισμού ομάδας, βιογραφικά","",1,false,["kitchen"]],["ΠΒ-2","Περιγράφονται τα προϊόντα (σύνθεση, συντήρηση, διάρκεια ζωής) και η χρήση τους, με ειδική αναφορά στους ευάλωτους ασθενείς;","Περιγραφές προϊόντων / συνταγών","",1,false,["kitchen"]],["ΠΒ-3","Υπάρχουν διαγράμματα ροής που επαληθεύτηκαν επί τόπου;","Διαγράμματα ροής με υπογραφή επαλήθευσης","",1,false,["kitchen"]]]},{"r":"HACCP","t":"Οι 7 αρχές HACCP","q":[["Αρχή 1","Έχει γίνει ανάλυση κινδύνων (βιολογικοί, χημικοί, φυσικοί, αλλεργιογόνα) για κάθε βήμα, με εκτίμηση σοβαρότητας και πιθανότητας;","Ανάλυση κινδύνων","",2,true,["kitchen"]],["Αρχή 2","Έχουν καθοριστεί τα κρίσιμα σημεία ελέγχου (CCP) με τεκμηριωμένη λογική (π.χ. δέντρο αποφάσεων);","Πίνακας CCP, δέντρο αποφάσεων","",2,true,["kitchen"]],["Αρχή 3","Έχουν οριστεί κρίσιμα όρια για κάθε CCP (π.χ. θερμοκρασία πυρήνα ≥ 75 °C, ψύξη σε 90 λεπτά) με επιστημονική βάση;","Πίνακας κρίσιμων ορίων","",2,true,["kitchen"]],["Αρχή 4","Παρακολουθείται κάθε CCP με καθορισμένη μέθοδο, συχνότητα και υπεύθυνο;","Πλάνο παρακολούθησης CCP","",2,true,["kitchen"]],["Αρχή 4","Είναι οι καταγραφές CCP πλήρεις, υπογεγραμμένες και εντός ορίων κατά το δείγμα που ελέγχθηκε;","Αρχεία CCP (Κουζίνα): μαγείρεμα, ψύξη, αναθέρμανση","Ελέγξτε τις καταγραφές των τελευταίων 2 εβδομάδων.",2,true,["kitchen"]],["Αρχή 5","Έχουν οριστεί διορθωτικές ενέργειες όταν ένα CCP βγει εκτός ορίων, και καταγράφονται (απόρριψη, επαναθέρμανση, απόσυρση);","Αρχεία διορθωτικών ενεργειών","",2,true,["kitchen"]],["Αρχή 6","Επαληθεύεται ότι το σύστημα HACCP λειτουργεί (ανασκόπηση αρχείων, μικροβιολογικοί έλεγχοι, εσωτερικοί έλεγχοι);","Αρχεία επαλήθευσης, αναλύσεις τροφίμων","",1,false,["kitchen"]],["Αρχή 6","Επανεξετάζεται το σχέδιο HACCP όταν αλλάζουν συνταγές, προμηθευτές, εξοπλισμός ή μετά από συμβάν;","Ιστορικό αναθεωρήσεων σχεδίου","",1,false,["kitchen"]],["Αρχή 7","Τηρούνται τα έγγραφα και τα αρχεία του HACCP για τον απαιτούμενο χρόνο και είναι διαθέσιμα;","Φάκελος HACCP","",1,false,["kitchen"]]]},{"r":"CCP","t":"Παρακολούθηση κρίσιμων σημείων στην πράξη","q":[["CCP-Μ","Μετρά το προσωπικό τη θερμοκρασία πυρήνα στο μαγείρεμα με καθαρό, απολυμασμένο θερμόμετρο;","Παρατήρηση μέτρησης","",2,true,["kitchen"]],["CCP-Ψ","Ψύχονται τα μαγειρεμένα τρόφιμα γρήγορα (ψυκτικός θάλαμος ταχείας ψύξης) με καταγραφή χρόνου και θερμοκρασίας;","Αρχεία ταχείας ψύξης","",2,true,["kitchen"]],["CCP-Α","Αναθερμαίνονται τα τρόφιμα μία μόνο φορά και σε επαρκή θερμοκρασία;","Αρχεία αναθέρμανσης","",1,false,["kitchen"]],["CCP-Δ","Διατηρούνται ζεστά τα φαγητά ως τη διανομή σε θερμοκρασία ασφάλειας και απορρίπτονται μετά τον καθορισμένο χρόνο;","Καταγραφές bain-marie","",1,false,["kitchen"]],["CCP-Ε","Ετοιμάζονται οι ειδικές διατροφές (χωρίς γλουτένη, αλλεργιογόνα, θρυμματισμένες) με ξεχωριστό εξοπλισμό και σήμανση δίσκου;","Παρατήρηση, κάρτες δίσκου","",2,true,["kitchen"]],["CCP-Δ","Κρατούνται δείγματα γευμάτων (μάρτυρες) για τον καθορισμένο χρόνο;","Αρχείο δειγμάτων-μαρτύρων","",1,false,["kitchen"]]]},{"r":"ISO 22000","t":"Σύστημα διαχείρισης ασφάλειας τροφίμων","q":[["5.2","Υπάρχει πολιτική ασφάλειας τροφίμων γνωστή στο προσωπικό της κουζίνας;","Πολιτική, συνεντεύξεις","",1,false,["kitchen"]],["6.2","Έχουν οριστεί στόχοι ασφάλειας τροφίμων (π.χ. αποκλίσεις θερμοκρασίας, παράπονα, αποτελέσματα αναλύσεων);","Στόχοι και δείκτες κουζίνας","",1,false,["kitchen"]],["7.4","Επικοινωνεί η κουζίνα με τα κλινικά τμήματα για τις διατροφικές ανάγκες και τις αλλεργίες των ασθενών;","Διαδικασία παραγγελίας διατροφής","",1,false,["kitchen"]],["8.4","Υπάρχει σχέδιο ετοιμότητας για έκτακτες καταστάσεις (διακοπή ρεύματος, βλάβη ψύξης, τροφιμογενής έξαρση);","Σχέδιο έκτακτης ανάγκης κουζίνας","",1,false,["kitchen"]],["8.9","Διαχειρίζονται τα δυνητικά μη ασφαλή προϊόντα (σήμανση, απομόνωση, απόφαση διάθεσης);","Αρχείο μη ασφαλών προϊόντων","",2,true,["kitchen"]],["9.1","Αναλύονται τα αποτελέσματα παρακολούθησης, οι αναλύσεις και τα παράπονα για τα γεύματα;","Αναφορές τάσεων, παράπονα","",1,false,["kitchen"]],["9.2","Γίνονται εσωτερικές επιθεωρήσεις του συστήματος ασφάλειας τροφίμων;","Πρόγραμμα, εκθέσεις","",1,false,["kitchen"]],["10.1","Αντιμετωπίζονται οι μη συμμορφώσεις με διορθωτικές ενέργειες και ανάλυση αιτίας;","CAPA κουζίνας","",1,false,["kitchen"]]]}]}'::jsonb j),
tp as (insert into public.quality_audit_templates (organization_id, is_system, template_key, standard, standard_version, title, description, scope, department_types, active, version, source)
 select null, true, j->>'k', j->>'s', j->>'v', j->>'t', 'Βοήθημα επιθεώρησης για το ' || (j->>'t') || ': ερωτήσεις διατυπωμένες με δικά μας λόγια, με αναφορά στο άρθρο ή το κεφάλαιο. Δεν αποτελεί το κείμενο του προτύπου, που παραμένει η πηγή αναφοράς. Επεξεργάσιμο: δημιουργήστε αντίγραφο για το νοσοκομείο σας και προσαρμόστε το.', j->>'sc', array(select jsonb_array_elements_text(j->'dt')), true, 1, 'seed' from s
 on conflict on constraint quality_audit_templates_title_key do nothing returning id),
qs as (select ch.value->>'r' r, ch.value->>'t' t, q.value v, row_number() over (order by ch.ordinality, q.ordinality) p
 from s, jsonb_array_elements(j->'ch') with ordinality ch, jsonb_array_elements(ch.value->'q') with ordinality q)
insert into public.quality_audit_template_questions (template_id, organization_id, position, chapter_ref, chapter_title, clause_ref, question, guidance, evidence, weight, critical, areas)
select tp.id, null, qs.p, qs.r, qs.t, qs.v->>0, qs.v->>1, nullif(qs.v->>3, ''), nullif(qs.v->>2, ''), (qs.v->>4)::numeric, (qs.v->>5)::boolean, array(select jsonb_array_elements_text(qs.v->6)) from tp, qs;

with s as (select '{"k":"iso15189","s":"iso15189","v":"2022","t":"ISO 15189:2022 — Ιατρικά εργαστήρια","sc":"Εργαστήρια (μικροβιολογικό, βιοχημικό, αιματολογικό, αιμοδοσία, παθολογοανατομικό) και δειγματοληψία στα κλινικά τμήματα.","dt":["laboratory"],"ch":[{"r":"4","t":"Γενικές απαιτήσεις","q":[["4.1","Έχουν εντοπιστεί και αντιμετωπίζονται οι κίνδυνοι για την αμεροληψία του εργαστηρίου (οικονομικές ή άλλες πιέσεις);","Δήλωση αμεροληψίας, ανάλυση κινδύνων αμεροληψίας","",1,false,["laboratory"]],["4.2","Δεσμεύεται το προσωπικό για την εμπιστευτικότητα των πληροφοριών των ασθενών;","Υπογεγραμμένες δηλώσεις, έλεγχος πρόσβασης","",1,false,["laboratory"]],["4.3","Λαμβάνει το εργαστήριο υπόψη την ευημερία, την ασφάλεια και τα δικαιώματα του ασθενή σε όλες τις δραστηριότητές του;","Διαδικασίες για ασθενείς, παράπονα","",1,false,["laboratory"]]]},{"r":"5","t":"Δομή και διακυβέρνηση","q":[["5.1","Έχει το εργαστήριο νομική υπόσταση ή σαφή θέση στον οργανισμό και ορισμένο διευθυντή με την απαιτούμενη επάρκεια;","Οργανόγραμμα, ορισμός διευθυντή, προσόντα","",1,false,["laboratory"]],["5.3","Είναι τεκμηριωμένο το εύρος των εξετάσεων που προσφέρει το εργαστήριο, και όσες γίνονται εκτός μόνιμων εγκαταστάσεων;","Κατάλογος εξετάσεων, πεδίο διαπίστευσης","",1,false,["laboratory"]],["5.4","Είναι ορισμένοι οι ρόλοι, οι αρμοδιότητες και οι αναπληρωτές για τις βασικές λειτουργίες του εργαστηρίου;","Περιγραφές θέσεων, αναθέσεις","",1,false,["laboratory"]],["5.5","Υπάρχουν μετρήσιμοι στόχοι ποιότητας για το εργαστήριο (π.χ. χρόνος απόκρισης, απορριπτέα δείγματα);","Στόχοι και δείκτες εργαστηρίου","",1,false,["laboratory"]],["5.6","Εντοπίζονται και αντιμετωπίζονται οι κίνδυνοι για τον ασθενή από τις εργαστηριακές διεργασίες;","Ανάλυση κινδύνων εργαστηρίου","",2,true,["laboratory"]]]},{"r":"6","t":"Απαιτήσεις πόρων","q":[["6.2","Έχει κάθε μέλος του προσωπικού τεκμηριωμένη εκπαίδευση, αξιολόγηση επάρκειας και εξουσιοδότηση για τις εξετάσεις που εκτελεί;","Ατομικοί φάκελοι, πίνακας εξουσιοδοτήσεων","",2,true,["laboratory"]],["6.2","Επαναξιολογείται περιοδικά η επάρκεια του προσωπικού και μετά από απουσία ή αλλαγή μεθόδου;","Αρχεία επαναξιολόγησης","",1,false,["laboratory"]],["6.3","Είναι κατάλληλοι οι χώροι και ελέγχονται οι περιβαλλοντικές συνθήκες που επηρεάζουν τα αποτελέσματα (θερμοκρασία, υγρασία);","Καταγραφές θερμοκρασίας / υγρασίας, όρια","",1,false,["laboratory"]],["6.3","Είναι διαχωρισμένοι οι χώροι με ασύμβατες δραστηριότητες και ελέγχεται η πρόσβαση;","Κάτοψη, έλεγχος πρόσβασης","",1,false,["laboratory"]],["6.4","Επαληθεύεται κάθε αναλυτής πριν από τη χρήση και συντηρείται σύμφωνα με τον κατασκευαστή;","Φάκελοι εξοπλισμού, αρχεία συντήρησης","",2,true,["laboratory"]],["6.4","Τίθεται εκτός χρήσης και σημαίνεται ο εξοπλισμός με βλάβη, και αξιολογείται η επίπτωση σε προηγούμενα αποτελέσματα;","Ετικέτες «εκτός λειτουργίας», αρχεία αξιολόγησης","",1,false,["laboratory"]],["6.5","Διακριβώνεται ο εξοπλισμός με μετρολογική ιχνηλασιμότητα (πιπέτες, θερμόμετρα, ζυγοί, φυγόκεντροι);","Πιστοποιητικά διακρίβωσης","",2,true,["laboratory"]],["6.6","Ελέγχονται κατά την παραλαβή τα αντιδραστήρια και αναλώσιμα, φυλάσσονται σωστά και καταγράφεται η παρτίδα και η λήξη;","Αρχείο παραλαβής, απογραφή, ετικέτες ανοίγματος","",1,false,["laboratory"]],["6.6","Επαληθεύεται μια νέα παρτίδα αντιδραστηρίου πριν τεθεί σε χρήση;","Αρχεία σύγκρισης παρτίδων","",1,false,["laboratory"]],["6.7","Συμφωνούνται με τους χρήστες (κλινικά τμήματα) οι απαιτήσεις και ανασκοπούνται οι συμφωνίες;","Συμφωνίες εξυπηρέτησης, ανασκοπήσεις","",1,false,["laboratory"]],["6.8","Επιλέγονται και παρακολουθούνται τα εργαστήρια αναφοράς και οι σύμβουλοι, και αναφέρεται στον χρήστη ποιος εκτέλεσε την εξέταση;","Λίστα εργαστηρίων αναφοράς, αξιολογήσεις","",1,false,["laboratory"]]]},{"r":"7.2","t":"Διεργασίες πριν από την εξέταση","q":[["7.2.2","Είναι διαθέσιμος στους χρήστες οδηγός εξετάσεων με οδηγίες προετοιμασίας, λήψης και μεταφοράς δειγμάτων;","Οδηγός λήψης δειγμάτων, διαθεσιμότητα στα τμήματα","",1,false,["laboratory"]],["7.2.3","Περιέχει το παραπεμπτικό τα απαραίτητα στοιχεία (ταυτοποίηση, εξέταση, κλινικές πληροφορίες, ώρα λήψης, αιτών);","Δείγμα παραπεμπτικών","",1,false,["laboratory"]],["7.2.4","Ταυτοποιείται ο ασθενής κατά τη λήψη και σημαίνεται το δείγμα δίπλα στον ασθενή;","Παρατήρηση δειγματοληψίας","Παρατηρήστε μία αιμοληψία στο τμήμα.",2,true,[]],["7.2.5","Μεταφέρονται τα δείγματα εντός χρόνου και θερμοκρασίας που διατηρούν την ακεραιότητά τους, με ασφάλεια;","Καταγραφές μεταφοράς, περιέκτες","",1,false,["laboratory"]],["7.2.6","Υπάρχουν κριτήρια αποδοχής / απόρριψης δειγμάτων και καταγράφονται οι απορρίψεις με ενημέρωση του αιτούντα;","Αρχείο απορριφθέντων δειγμάτων","",2,true,["laboratory"]],["7.2.7","Φυλάσσονται τα δείγματα πριν την εξέταση σε συνθήκες που προστατεύουν τη σταθερότητά τους;","Ψυγεία, καταγραφές","",1,false,["laboratory"]]]},{"r":"7.3","t":"Διεργασίες εξέτασης","q":[["7.3.2","Έχει επαληθευτεί κάθε επικυρωμένη μέθοδος πριν από τη χρήση (ακρίβεια, πιστότητα, εύρος);","Φάκελοι επαλήθευσης μεθόδων","",2,true,["laboratory"]],["7.3.3","Επικυρώνονται οι μέθοδοι που αναπτύχθηκαν ή τροποποιήθηκαν από το εργαστήριο;","Φάκελοι επικύρωσης","",1,false,["laboratory"]],["7.3.4","Έχει εκτιμηθεί η αβεβαιότητα μέτρησης για τις ποσοτικές εξετάσεις και ανασκοπείται;","Υπολογισμοί αβεβαιότητας","",1,false,["laboratory"]],["7.3.5","Έχουν καθοριστεί και τεκμηριωθεί τα διαστήματα αναφοράς και τα όρια κλινικής απόφασης;","Τεκμηρίωση διαστημάτων αναφοράς","",1,false,["laboratory"]],["7.3.6","Είναι οι διαδικασίες εξέτασης γραμμένες, διαθέσιμες στο σημείο εργασίας και στην τρέχουσα έκδοση;","SOP στον πάγκο εργασίας","",1,false,["laboratory"]],["7.3.7","Τρέχει ο εσωτερικός ποιοτικός έλεγχος με καθορισμένη συχνότητα και κανόνες αποδοχής (π.χ. Westgard), και τεκμηριώνονται οι ενέργειες όταν αποτυγχάνει;","Διαγράμματα Levey-Jennings, αρχεία ενεργειών","",2,true,["laboratory"]],["7.3.7","Συμμετέχει το εργαστήριο σε εξωτερικό έλεγχο ποιότητας και διερευνώνται τα μη αποδεκτά αποτελέσματα;","Αναφορές EQA, διερευνήσεις","",2,true,["laboratory"]],["7.3.7","Συγκρίνονται τα αποτελέσματα όταν η ίδια εξέταση γίνεται σε διαφορετικούς αναλυτές ή σημεία;","Αρχεία συγκρισιμότητας","",1,false,["laboratory"]]]},{"r":"7.4","t":"Διεργασίες μετά την εξέταση","q":[["7.4.1","Ανασκοπούνται και εγκρίνονται τα αποτελέσματα από εξουσιοδοτημένο προσωπικό πριν από την αποδέσμευση;","Ίχνη έγκρισης στο LIS","",2,true,["laboratory"]],["7.4.1","Περιέχει η έκθεση αποτελεσμάτων όλα τα απαιτούμενα στοιχεία (ταυτοποίηση, μονάδες, όρια, σχόλια, ποιος ενέκρινε);","Δείγμα εκθέσεων","",1,false,["laboratory"]],["7.4.1","Κοινοποιούνται άμεσα οι κρίσιμες τιμές και καταγράφεται ποιος ενημερώθηκε και πότε;","Αρχείο κρίσιμων τιμών","",2,true,["laboratory"]],["7.4.1","Παρακολουθείται ο χρόνος απόκρισης (TAT) έναντι στόχων;","Δείκτης TAT","",1,false,["laboratory"]],["7.4.1","Τροποποιούνται τα αποτελέσματα ελεγχόμενα, με διατήρηση της αρχικής έκδοσης και ενημέρωση του χρήστη;","Ίχνη τροποποιήσεων","",1,false,["laboratory"]],["7.4.2","Φυλάσσονται και απορρίπτονται τα δείγματα μετά την εξέταση με ασφάλεια και για τον καθορισμένο χρόνο;","Πολιτική διατήρησης δειγμάτων","",1,false,["laboratory"]]]},{"r":"7.5–7.8","t":"Μη συμμορφούμενη εργασία, δεδομένα, παράπονα, συνέχεια","q":[["7.5","Διαχειρίζεται η μη συμμορφούμενη εργασία με διακοπή, αξιολόγηση επίπτωσης, ανάκληση αποτελεσμάτων όπου χρειάζεται;","Αρχείο μη συμμορφώσεων","",2,true,["laboratory"]],["7.6","Είναι επικυρωμένο το εργαστηριακό πληροφοριακό σύστημα και προστατευμένο από μη εξουσιοδοτημένη πρόσβαση;","Επικύρωση LIS, δικαιώματα χρηστών","",1,false,["laboratory"]],["7.6","Ελέγχεται η σωστή μεταφορά δεδομένων από τους αναλυτές στο LIS και στον φάκελο;","Έλεγχοι διασύνδεσης","",1,false,["laboratory"]],["7.7","Καταγράφονται, διερευνώνται και απαντώνται τα παράπονα των χρηστών;","Μητρώο παραπόνων","",1,false,["laboratory"]],["7.8","Υπάρχει σχέδιο συνέχειας λειτουργίας για βλάβες, διακοπή ρεύματος ή συστήματος;","Σχέδιο έκτακτης ανάγκης, δοκιμές","",1,false,["laboratory"]]]},{"r":"8","t":"Σύστημα διαχείρισης","q":[["8.3","Ελέγχονται τα έγγραφα του εργαστηρίου (έκδοση, έγκριση, ανασκόπηση, απόσυρση);","Λίστα εγγράφων","",1,false,["laboratory"]],["8.4","Τηρούνται τα αρχεία ποιότητας και τα τεχνικά αρχεία για τον καθορισμένο χρόνο και είναι ανακτήσιμα;","Δειγματοληψία αρχείων","",1,false,["laboratory"]],["8.5","Αξιολογείται η αποτελεσματικότητα των ενεργειών για κινδύνους και ευκαιρίες βελτίωσης;","Αρχεία ενεργειών","",1,false,["laboratory"]],["8.6","Συλλέγεται ανατροφοδότηση από ασθενείς και χρήστες και αξιοποιείται για βελτίωση;","Έρευνες χρηστών","",1,false,["laboratory"]],["8.7","Αναλύονται οι ριζικές αιτίες των μη συμμορφώσεων και επαληθεύονται οι διορθωτικές ενέργειες;","CAPA εργαστηρίου","",1,false,["laboratory"]],["8.8","Γίνονται εσωτερικές επιθεωρήσεις που καλύπτουν όλο το εύρος και όλες τις διεργασίες σε κύκλο;","Πρόγραμμα εσωτερικών επιθεωρήσεων","",1,false,["laboratory"]],["8.8","Παρακολουθούνται δείκτες ποιότητας σε όλες τις φάσεις (πριν, κατά και μετά την εξέταση);","Πίνακας δεικτών ποιότητας εργαστηρίου","",1,false,["laboratory"]],["8.9","Ανασκοπεί η διοίκηση του εργαστηρίου το σύστημα με τα απαιτούμενα δεδομένα εισόδου;","Πρακτικά ανασκόπησης","",1,false,["laboratory"]]]}]}'::jsonb j),
tp as (insert into public.quality_audit_templates (organization_id, is_system, template_key, standard, standard_version, title, description, scope, department_types, active, version, source)
 select null, true, j->>'k', j->>'s', j->>'v', j->>'t', 'Βοήθημα επιθεώρησης για το ' || (j->>'t') || ': ερωτήσεις διατυπωμένες με δικά μας λόγια, με αναφορά στο άρθρο ή το κεφάλαιο. Δεν αποτελεί το κείμενο του προτύπου, που παραμένει η πηγή αναφοράς. Επεξεργάσιμο: δημιουργήστε αντίγραφο για το νοσοκομείο σας και προσαρμόστε το.', j->>'sc', array(select jsonb_array_elements_text(j->'dt')), true, 1, 'seed' from s
 on conflict on constraint quality_audit_templates_title_key do nothing returning id),
qs as (select ch.value->>'r' r, ch.value->>'t' t, q.value v, row_number() over (order by ch.ordinality, q.ordinality) p
 from s, jsonb_array_elements(j->'ch') with ordinality ch, jsonb_array_elements(ch.value->'q') with ordinality q)
insert into public.quality_audit_template_questions (template_id, organization_id, position, chapter_ref, chapter_title, clause_ref, question, guidance, evidence, weight, critical, areas)
select tp.id, null, qs.p, qs.r, qs.t, qs.v->>0, qs.v->>1, nullif(qs.v->>3, ''), nullif(qs.v->>2, ''), (qs.v->>4)::numeric, (qs.v->>5)::boolean, array(select jsonb_array_elements_text(qs.v->6)) from tp, qs;

with s as (select '{"k":"temos","s":"temos","v":"2023","t":"TEMOS — Ποιότητα στη φροντίδα διεθνών ασθενών","sc":"Γραφείο διεθνών ασθενών και τα κλινικά τμήματα που νοσηλεύουν διεθνείς ασθενείς: επικοινωνία, διερμηνεία, πληροφόρηση, συντονισμός, διαμονή και ταξίδι, παρακολούθηση, παράπονα.","dt":["international","clinical"],"ch":[{"r":"T1","t":"Υπηρεσία διεθνών ασθενών","q":[["T1.1","Υπάρχει ορισμένο γραφείο ή υπεύθυνος για τους διεθνείς ασθενείς με σαφείς αρμοδιότητες και ωράριο;","Οργανόγραμμα, περιγραφές θέσεων","",2,true,["international"]],["T1.2","Είναι γραμμένες οι διαδικασίες για όλη τη διαδρομή του διεθνούς ασθενή (αίτημα, προσφορά, άφιξη, νοσηλεία, αναχώρηση);","Διαδικασίες, διάγραμμα διαδρομής","",1,false,["international"]],["T1.3","Παρακολουθούνται δείκτες της υπηρεσίας (χρόνος απάντησης σε αίτημα, ικανοποίηση, παράπονα);","Δείκτες γραφείου διεθνών ασθενών","",1,false,["international"]],["T1.4","Είναι εκπαιδευμένο το προσωπικό που εξυπηρετεί διεθνείς ασθενείς στη διαπολιτισμική επικοινωνία;","Αρχεία εκπαίδευσης","",1,false,["international"]],["T1.5","Ελέγχονται οι συνεργάτες (πράκτορες, ασφαλιστές, διευκολυντές) με συμβάσεις και αξιολογήσεις;","Συμβάσεις, αξιολογήσεις συνεργατών","",1,false,["international"]]]},{"r":"T2","t":"Επικοινωνία και διερμηνεία","q":[["T2.1","Απαντώνται τα αιτήματα των υποψήφιων ασθενών εντός του καθορισμένου χρόνου και στη γλώσσα τους;","Αρχείο αιτημάτων με χρόνους","",1,false,["international"]],["T2.2","Διατίθεται επαγγελματική διερμηνεία στις κλινικές συζητήσεις, χωρίς να χρησιμοποιούνται συγγενείς για ιατρικές πληροφορίες;","Διαδικασία διερμηνείας, αρχεία κρατήσεων διερμηνέων","",2,true,[]],["T2.3","Μεταφράζονται επίσημα τα σημαντικά έγγραφα (συγκατάθεση, σημείωμα εξόδου, ιατρική έκθεση);","Μεταφρασμένα έγγραφα, διαδικασία μετάφρασης","",1,false,["international"]],["T2.4","Υπάρχει σημείο επικοινωνίας 24 ώρες για τον ασθενή και τη συνοδεία του;","Τηλέφωνο έκτακτης ανάγκης, πρόγραμμα κάλυψης","",1,false,["international"]],["T2.5","Επικοινωνεί το νοσοκομείο με τον θεράποντα ιατρό στη χώρα του ασθενή πριν και μετά τη θεραπεία;","Αλληλογραφία με θεράποντα","",1,false,["international"]]]},{"r":"T3","t":"Πληροφόρηση και διαφάνεια","q":[["T3.1","Λαμβάνει ο ασθενής πριν το ταξίδι γραπτή πληροφόρηση για τη θεραπεία, τους κινδύνους, τη διάρκεια παραμονής και την ανάρρωση;","Πακέτο πληροφόρησης","",2,true,["international"]],["T3.2","Δίνεται σαφής γραπτή προσφορά κόστους με όσα περιλαμβάνει και δεν περιλαμβάνει, και πολιτική για επιπλέον χρεώσεις;","Προσφορές, όροι","",2,true,["international"]],["T3.3","Γνωρίζει ο ασθενής τα δικαιώματά του, τον τρόπο υποβολής παραπόνων και το εφαρμοστέο δίκαιο;","Χάρτης δικαιωμάτων σε ξένες γλώσσες","",1,false,["international"]],["T3.4","Είναι οι πληροφορίες της ιστοσελίδας για διεθνείς ασθενείς ακριβείς, επικαιροποιημένες και χωρίς παραπλανητικές υποσχέσεις;","Έλεγχος ιστοσελίδας","",1,false,["international"]],["T3.5","Πληροφορείται ο ασθενής για τα προσόντα των ιατρών που θα τον φροντίσουν;","Παρουσίαση ιατρών, βιογραφικά","",1,false,["international"]]]},{"r":"T4","t":"Συντονισμός της φροντίδας","q":[["T4.1","Αξιολογούνται τα ιατρικά στοιχεία του ασθενή πριν από την αποδοχή, ώστε να επιβεβαιωθεί ότι η θεραπεία είναι κατάλληλη και εφικτή;","Αρχεία προαξιολόγησης, γνωμάτευση ιατρού","",2,true,[]],["T4.2","Έχει κάθε διεθνής ασθενής ορισμένο συντονιστή (case manager) από την άφιξη ως την αναχώρηση;","Ανάθεση συντονιστή","",1,false,["international"]],["T4.3","Συντονίζονται τα ραντεβού, οι εξετάσεις και η επέμβαση ώστε να αποφεύγονται περιττές καθυστερήσεις;","Πρόγραμμα ασθενή","",1,false,["international"]],["T4.4","Ενημερώνεται το κλινικό τμήμα πριν την άφιξη για γλώσσα, διατροφή, θρησκευτικές ή άλλες ιδιαιτερότητες;","Σημείωμα προετοιμασίας τμήματος","",1,false,["international","clinical"]],["T4.5","Υπάρχει σχέδιο για επιπλοκές που απαιτούν παράταση παραμονής ή επαναπατρισμό;","Διαδικασία επιπλοκών, συμφωνίες ασφαλιστών","",2,true,["international"]]]},{"r":"T5","t":"Διαμονή, ταξίδι και υποστήριξη","q":[["T5.1","Βοηθά το γραφείο στην οργάνωση του ταξιδιού (βίζα, πτήσεις, μεταφορά από / προς το αεροδρόμιο);","Αρχεία υποστήριξης ταξιδιού","",1,false,["international"]],["T5.2","Προτείνονται κατάλληλα καταλύματα για τον ασθενή και τη συνοδεία, προσβάσιμα και κοντά στο νοσοκομείο;","Λίστα συνεργαζόμενων καταλυμάτων","",1,false,["international"]],["T5.3","Γνωρίζει ο ασθενής πότε μπορεί με ασφάλεια να ταξιδέψει μετά τη θεραπεία (fit to fly);","Οδηγίες, γνωμάτευση πριν την αναχώρηση","",2,true,["international"]],["T5.4","Προσφέρονται υπηρεσίες υποστήριξης (συνάλλαγμα, SIM, θρησκευτική φροντίδα, διατροφικές επιλογές);","Κατάλογος υπηρεσιών","",1,false,["international"]]]},{"r":"T6","t":"Κλινική ποιότητα και ασφάλεια","q":[["T6.1","Εφαρμόζονται για τους διεθνείς ασθενείς τα ίδια πρωτόκολλα ασφάλειας με όλους (ταυτοποίηση, συγκατάθεση, χειρουργική λίστα);","Δείγμα φακέλων διεθνών ασθενών","",1,true,["international","clinical"]],["T6.2","Ελέγχονται κατά την εισαγωγή οι πολυανθεκτικοί μικροοργανισμοί όταν ο ασθενής έρχεται από χώρα ή νοσοκομείο υψηλού κινδύνου;","Πρωτόκολλο ελέγχου εισαγωγής, αποτελέσματα","",1,true,["international","clinical"]],["T6.3","Είναι η ενημερωμένη συγκατάθεση σε γλώσσα που κατανοεί ο ασθενής, με υπογραφή διερμηνέα όπου χρειάζεται;","Έντυπα συγκατάθεσης","",2,true,["international"]],["T6.4","Καταγράφονται και διερευνώνται τα συμβάντα που αφορούν διεθνείς ασθενείς;","Αναφορές συμβάντων","",1,false,["international"]]]},{"r":"T7","t":"Παρακολούθηση και συνέχεια","q":[["T7.1","Λαμβάνει ο ασθενής κατά την αναχώρηση πλήρη ιατρική έκθεση, εικόνες και αποτελέσματα στη γλώσσα του;","Πακέτο εξόδου","",2,true,["international"]],["T7.2","Υπάρχει σχέδιο παρακολούθησης μετά την επιστροφή (τηλεσυμβουλευτική, επικοινωνία με θεράποντα);","Αρχεία παρακολούθησης","",1,false,["international"]],["T7.3","Γίνεται επικοινωνία με τον ασθενή μετά την επιστροφή για έλεγχο της πορείας και επιπλοκών;","Αρχεία κλήσεων παρακολούθησης","",1,false,["international"]],["T7.4","Διαβιβάζονται τα δεδομένα υγείας στο εξωτερικό με νόμιμο και ασφαλή τρόπο;","Διαδικασία διαβίβασης, συναίνεση","",1,false,["international"]]]},{"r":"T8","t":"Παράπονα και ανατροφοδότηση","q":[["T8.1","Συλλέγεται η γνώμη κάθε διεθνούς ασθενή πριν φύγει ή μετά την επιστροφή του;","Ερωτηματολόγια σε ξένες γλώσσες","",1,false,["international"]],["T8.2","Καταγράφονται και απαντώνται τα παράπονα των διεθνών ασθενών εντός προθεσμίας, στη γλώσσα τους;","Μητρώο παραπόνων","",2,true,["international"]],["T8.3","Υπάρχει διαδικασία για οικονομικές διαφορές και επιστροφές χρημάτων;","Διαδικασία, αρχεία","",1,false,["international"]],["T8.4","Αξιοποιούνται τα παράπονα και η ανατροφοδότηση για βελτιώσεις της υπηρεσίας;","Σχέδιο βελτίωσης","",1,false,["international"]]]}]}'::jsonb j),
tp as (insert into public.quality_audit_templates (organization_id, is_system, template_key, standard, standard_version, title, description, scope, department_types, active, version, source)
 select null, true, j->>'k', j->>'s', j->>'v', j->>'t', 'Βοήθημα επιθεώρησης για το ' || (j->>'t') || ': ερωτήσεις διατυπωμένες με δικά μας λόγια, με αναφορά στο άρθρο ή το κεφάλαιο. Δεν αποτελεί το κείμενο του προτύπου, που παραμένει η πηγή αναφοράς. Επεξεργάσιμο: δημιουργήστε αντίγραφο για το νοσοκομείο σας και προσαρμόστε το.', j->>'sc', array(select jsonb_array_elements_text(j->'dt')), true, 1, 'seed' from s
 on conflict on constraint quality_audit_templates_title_key do nothing returning id),
qs as (select ch.value->>'r' r, ch.value->>'t' t, q.value v, row_number() over (order by ch.ordinality, q.ordinality) p
 from s, jsonb_array_elements(j->'ch') with ordinality ch, jsonb_array_elements(ch.value->'q') with ordinality q)
insert into public.quality_audit_template_questions (template_id, organization_id, position, chapter_ref, chapter_title, clause_ref, question, guidance, evidence, weight, critical, areas)
select tp.id, null, qs.p, qs.r, qs.t, qs.v->>0, qs.v->>1, nullif(qs.v->>3, ''), nullif(qs.v->>2, ''), (qs.v->>4)::numeric, (qs.v->>5)::boolean, array(select jsonb_array_elements_text(qs.v->6)) from tp, qs;

with s as (select '{"k":"jci","s":"jci","v":"8η έκδοση","t":"JCI — Πρότυπα νοσοκομείων (Joint Commission International)","sc":"Όλο το νοσοκομείο: στόχοι ασφάλειας ασθενών, κλινικά κεφάλαια (ACC, PCC, AOP, ASC, MMU, PFE, PCI) και κεφάλαια διοίκησης (QPS, GLD, FMS, SQE, MOI).","dt":[],"ch":[{"r":"IPSG","t":"Διεθνείς στόχοι ασφάλειας ασθενών","q":[["IPSG.1","Ταυτοποιείται ο ασθενής με δύο τουλάχιστον στοιχεία (όχι αριθμό θαλάμου ή κλίνης) πριν από φάρμακα, αίμα, δείγματα και πράξεις;","Παρατήρηση, βραχιόλια","",3,true,[]],["IPSG.2","Χρησιμοποιείται η διαδικασία «γράφω – διαβάζω πίσω – επιβεβαιώνω» στις προφορικές και τηλεφωνικές οδηγίες;","Παρατήρηση, έντυπα προφορικών οδηγιών","",2,true,["clinical"]],["IPSG.2","Αναφέρονται τα κρίσιμα αποτελέσματα στον υπεύθυνο ιατρό εντός καθορισμένου χρόνου και καταγράφεται;","Αρχείο κρίσιμων τιμών","",2,true,["clinical"]],["IPSG.2","Γίνεται η παράδοση-παραλαβή ασθενών με τυποποιημένο εργαλείο;","Έντυπο παράδοσης (SBAR)","",1,false,["clinical"]],["IPSG.3","Φυλάσσονται χωριστά και σημαίνονται τα φάρμακα υψηλού κινδύνου και τα «ηχητικά ή οπτικά όμοια» (LASA);","Επιθεώρηση φαρμάκων τμήματος","",2,true,["clinical"]],["IPSG.3","Απουσιάζουν από τα τμήματα τα πυκνά ηλεκτρολυτικά διαλύματα, εκτός όπου είναι κλινικά απαραίτητα και ασφαλισμένα;","Επιθεώρηση ερμαρίων","",2,true,["clinical"]],["IPSG.4","Σημαίνεται το σημείο επέμβασης και γίνεται επαλήθευση πριν από την επέμβαση;","Παρατήρηση, φάκελος","",2,true,["clinical"]],["IPSG.4","Γίνεται time-out με όλη την ομάδα αμέσως πριν από την τομή ή την επεμβατική πράξη, και τεκμηριώνεται;","Χειρουργική λίστα ελέγχου","",2,true,["clinical"]],["IPSG.5","Εφαρμόζεται πρόγραμμα υγιεινής χεριών βασισμένο σε τεκμηριωμένες οδηγίες, με μετρήσεις συμμόρφωσης;","Παρατηρήσεις υγιεινής χεριών","",2,true,[]],["IPSG.6","Αξιολογούνται οι ασθενείς για κίνδυνο πτώσης στην εισαγωγή και όταν αλλάζει η κατάσταση, με μέτρα πρόληψης;","Κλίμακες πτώσης, σχέδια φροντίδας","",2,true,["clinical"]]]},{"r":"ACC","t":"Πρόσβαση και συνέχεια της φροντίδας","q":[["ACC.1","Γίνεται διαλογή ασθενών με βάση την επείγουσα ανάγκη και προτεραιοποιούνται οι επείγοντες;","Εργαλείο διαλογής ΤΕΠ","",1,false,["clinical"]],["ACC.2","Υπάρχουν κριτήρια εισαγωγής και εξόδου για τις μονάδες εντατικής και ειδικές μονάδες;","Κριτήρια εισαγωγής ΜΕΘ","",1,false,["clinical"]],["ACC.2","Ενημερώνονται ασθενής και οικογένεια κατά την εισαγωγή για τη φροντίδα, τα αναμενόμενα αποτελέσματα και το κόστος;","Έντυπα ενημέρωσης","",1,false,["clinical"]],["ACC.3","Ορίζεται υπεύθυνος για τη φροντίδα κάθε ασθενή σε όλη τη διάρκεια της νοσηλείας;","Φάκελος, πίνακας υπευθύνων","",1,false,["clinical"]],["ACC.3","Μεταφέρονται οι πληροφορίες του ασθενή μεταξύ τμημάτων και επαγγελματιών χωρίς απώλειες;","Σημειώματα μεταφοράς","",2,true,["clinical"]],["ACC.4","Σχεδιάζεται η έξοδος από νωρίς, με οδηγίες, παραπομπές και ενημέρωση της οικογένειας;","Σχέδιο εξόδου","",1,false,["clinical"]],["ACC.4","Περιλαμβάνει το σημείωμα εξόδου διάγνωση, θεραπεία, φάρμακα και οδηγίες παρακολούθησης;","Δείγμα σημειωμάτων εξόδου","",1,false,["clinical"]],["ACC.5","Γίνεται με ασφάλεια η διακομιδή σε άλλο νοσοκομείο, με συνοδεία και πληροφορίες;","Αρχεία διακομιδών","",1,false,["clinical"]]]},{"r":"PCC","t":"Φροντίδα με επίκεντρο τον ασθενή","q":[["PCC.1","Γίνονται σεβαστές οι αξίες, οι πεποιθήσεις και η ιδιωτικότητα του ασθενή;","Παρατήρηση, έρευνα εμπειρίας","",1,false,["clinical"]],["PCC.1","Προστατεύονται οι ευάλωτοι ασθενείς (παιδιά, ηλικιωμένοι, άτομα με αναπηρία) από κακοποίηση ή παραμέληση;","Διαδικασία προστασίας ευάλωτων","",1,false,["clinical"]],["PCC.2","Συμμετέχουν ασθενής και οικογένεια στις αποφάσεις φροντίδας και ενημερώνονται για τα αποτελέσματα, και τα απρόσμενα;","Φάκελος, πολιτική γνωστοποίησης","",1,false,["clinical"]],["PCC.3","Λαμβάνεται ενημερωμένη συγκατάθεση πριν από επεμβάσεις, αναισθησία, μεταγγίσεις και άλλες πράξεις υψηλού κινδύνου;","Έντυπα συγκατάθεσης","",2,true,["clinical"]],["PCC.4","Γίνονται σεβαστές οι επιθυμίες του ασθενή για την ανάνηψη και τη φροντίδα στο τέλος της ζωής;","Αρχεία DNR, παρηγορητική φροντίδα","",1,false,["clinical"]],["PCC.5","Ενημερώνονται οι ασθενείς για τη διαδικασία παραπόνων και τα παράπονα διερευνώνται;","Μητρώο παραπόνων","",1,false,[]]]},{"r":"AOP","t":"Αξιολόγηση ασθενών","q":[["AOP.1","Ολοκληρώνεται η αρχική ιατρική και νοσηλευτική αξιολόγηση εντός 24 ωρών (ή νωρίτερα όπου ορίζεται);","Δείγμα φακέλων με χρόνους","",2,true,["clinical"]],["AOP.1","Περιλαμβάνει η αρχική αξιολόγηση διατροφική, λειτουργική και πόνου, με παραπομπή όπου χρειάζεται;","Εργαλεία αξιολόγησης","",1,false,["clinical"]],["AOP.2","Επαναξιολογούνται οι ασθενείς σε διαστήματα ανάλογα με την κατάστασή τους;","Φάκελος","",1,false,["clinical"]],["AOP.4","Λειτουργεί το εργαστήριο με πρόγραμμα ποιότητας (εσωτερικός και εξωτερικός έλεγχος, χρόνοι απόκρισης);","Αρχεία ποιοτικού ελέγχου","",1,false,["laboratory"]],["AOP.4","Εφαρμόζεται πρόγραμμα ασφάλειας στο εργαστήριο (χημικοί και βιολογικοί κίνδυνοι);","Πρόγραμμα ασφάλειας εργαστηρίου","",1,false,["laboratory"]],["AOP.6","Εφαρμόζεται πρόγραμμα ακτινοπροστασίας στην απεικόνιση, με δοσιμετρία προσωπικού;","Δοσίμετρα, πρόγραμμα ακτινοπροστασίας","",1,false,[]]]},{"r":"COP","t":"Φροντίδα ασθενών","q":[["COP.2","Είναι ο σχεδιασμός της φροντίδας ενιαίος και καταγράφεται σε ένα σχέδιο φροντίδας στον φάκελο;","Σχέδια φροντίδας","",1,false,["clinical"]],["COP.3","Αναγνωρίζονται έγκαιρα οι αλλαγές στην κατάσταση του ασθενή (early warning score) και ενεργοποιείται βοήθεια;","Φύλλα NEWS, κλήσεις ομάδας ταχείας απόκρισης","",2,true,["clinical"]],["COP.3","Είναι διαθέσιμη σε όλο το νοσοκομείο ομάδα ανάνηψης με ελεγμένο εξοπλισμό;","Έλεγχοι τροχηλάτου ανάνηψης","",2,true,["clinical"]],["COP.3","Χορηγούνται αίμα και παράγωγα σύμφωνα με τη διαδικασία, με παρακολούθηση αντιδράσεων;","Φύλλα μετάγγισης","",1,false,["clinical"]],["COP.6","Αξιολογείται και αντιμετωπίζεται ο πόνος σύμφωνα με τα πρωτόκολλα;","Κλίμακες πόνου","",1,false,["clinical"]]]},{"r":"ASC","t":"Αναισθησία και χειρουργική φροντίδα","q":[["ASC.3","Παρακολουθείται ο ασθενής κατά την καταστολή από εκπαιδευμένο προσωπικό, με κριτήρια ανάνηψης;","Φύλλα καταστολής","",1,true,["clinical"]],["ASC.4","Γίνεται προαναισθητική εκτίμηση και επανεκτίμηση αμέσως πριν από την εισαγωγή στην αναισθησία;","Φύλλα αναισθησίας","",1,false,["clinical"]],["ASC.5","Καταγράφεται συνεχώς η παρακολούθηση κατά την αναισθησία και η έξοδος από την ανάνηψη γίνεται με κριτήρια;","Φύλλα ανάνηψης","",1,false,["clinical"]],["ASC.7","Τεκμηριώνονται η προεγχειρητική διάγνωση, το σχέδιο επέμβασης και η μετεγχειρητική έκθεση;","Χειρουργικός φάκελος","",1,false,["clinical"]],["ASC.7.4","Ιχνηλατούνται τα εμφυτεύσιμα ιατροτεχνολογικά προϊόντα ως τον ασθενή;","Αρχείο εμφυτευμάτων","",1,false,["clinical"]]]},{"r":"MMU","t":"Διαχείριση και χρήση φαρμάκων","q":[["MMU.1","Υπάρχει εγκεκριμένο συνταγολόγιο και διαδικασία για φάρμακα εκτός συνταγολογίου;","Συνταγολόγιο, εγκρίσεις","",1,false,[]],["MMU.3","Φυλάσσονται τα φάρμακα με ασφάλεια, σε σωστές θερμοκρασίες, χωρίς ληγμένα;","Επιθεώρηση ερμαρίων και ψυγείων φαρμάκων","",2,true,["clinical"]],["MMU.3","Ελέγχονται τα φάρμακα έκτακτης ανάγκης και είναι σφραγισμένα και πλήρη;","Λίστα ελέγχου τροχηλάτου","",1,false,["clinical"]],["MMU.3","Είναι ασφαλισμένα και καταγεγραμμένα τα ναρκωτικά και ελεγχόμενα φάρμακα;","Βιβλίο ναρκωτικών","",2,true,["clinical"]],["MMU.4","Είναι οι συνταγές πλήρεις και ευανάγνωστες, χωρίς μη εγκεκριμένες συντομογραφίες;","Δείγμα ιατρικών οδηγιών","",1,false,["clinical"]],["MMU.5","Ανασκοπείται κάθε συνταγή από φαρμακοποιό για καταλληλότητα, αλληλεπιδράσεις και αλλεργίες πριν τη διανομή;","Αρχεία φαρμακευτικής παρέμβασης","",1,false,[]],["MMU.5","Προετοιμάζονται τα στείρα φάρμακα σε καθαρό χώρο με ασηπτική τεχνική και σωστή επισήμανση;","Παρατήρηση προετοιμασίας","",1,false,[]],["MMU.6","Επαληθεύονται τα «5 σωστά» πριν από τη χορήγηση και καταγράφεται η χορήγηση;","Παρατήρηση, φύλλο χορήγησης","",2,true,["clinical"]],["MMU.7","Παρακολουθούνται οι ανεπιθύμητες ενέργειες και τα λάθη φαρμάκων, αναφέρονται και αναλύονται;","Αναφορές λαθών φαρμάκων","",1,false,["clinical"]]]},{"r":"PFE","t":"Εκπαίδευση ασθενών και οικογένειας","q":[["PFE.1","Αξιολογούνται οι εκπαιδευτικές ανάγκες του ασθενή και τα εμπόδια μάθησης (γλώσσα, γνωστικά);","Φάκελος, εργαλείο αξιολόγησης","",1,false,["clinical"]],["PFE.2","Εκπαιδεύεται ο ασθενής για τα φάρμακα, τη διατροφή, τον πόνο και τη χρήση εξοπλισμού, και τεκμηριώνεται;","Αρχεία εκπαίδευσης ασθενή","",1,false,["clinical"]],["PFE.3","Επιβεβαιώνεται ότι ο ασθενής κατάλαβε (teach-back);","Παρατήρηση, φάκελος","",1,false,["clinical"]],["PFE.4","Είναι το εκπαιδευτικό υλικό κατανοητό, επικαιροποιημένο και σε γλώσσες των ασθενών;","Φυλλάδια","",1,false,[]]]},{"r":"QPS","t":"Βελτίωση ποιότητας και ασφάλεια ασθενών","q":[["QPS.1","Υπάρχει πρόγραμμα ποιότητας και ασφάλειας ασθενών με επαρκή στελέχωση και υποστήριξη από την ηγεσία;","Πρόγραμμα, οργανόγραμμα ποιότητας","",1,false,["management"]],["QPS.2","Επιλέγονται δείκτες προτεραιότητας για όλο το νοσοκομείο και ανά τμήμα, με ορισμούς και στόχους;","Λίστα δεικτών με ορισμούς","",1,false,[]],["QPS.3","Επικυρώνονται τα δεδομένα των δεικτών (ακρίβεια, πληρότητα) πριν από τη δημοσίευση;","Αρχεία επικύρωσης δεδομένων","",1,false,["management"]],["QPS.4","Αναλύονται τα δεδομένα με στατιστικά εργαλεία και συγκρίνονται με εξωτερικές αναφορές;","Αναφορές τάσεων, benchmarking","",1,false,[]],["QPS.5","Διερευνώνται τα συμβάντα-φρουροί με ανάλυση ριζικής αιτίας εντός 45 ημερών;","RCA, ημερομηνίες","",2,true,[]],["QPS.6","Αναλύονται τα «παρ’ ολίγον» και τα ανεπιθύμητα συμβάντα για τάσεις;","Αναφορές τάσεων συμβάντων","",1,false,[]],["QPS.7","Γίνεται ετήσια προληπτική ανάλυση κινδύνου (π.χ. FMEA) σε μία τουλάχιστον διεργασία υψηλού κινδύνου;","FMEA","",1,false,["management"]],["QPS.8","Διατηρούνται οι βελτιώσεις που επιτεύχθηκαν και αξιολογούνται με νέα μέτρηση;","Επαναληπτικές μετρήσεις","",1,false,[]]]},{"r":"PCI","t":"Πρόληψη και έλεγχος λοιμώξεων","q":[["PCI.1","Συντονίζεται το πρόγραμμα ελέγχου λοιμώξεων από επαρκώς εκπαιδευμένο προσωπικό με ετήσιο σχέδιο;","Σχέδιο ΕΝΛ, εκθέσεις","",1,false,["management"]],["PCI.3","Βασίζεται το πρόγραμμα σε εκτίμηση κινδύνου λοιμώξεων που επικαιροποιείται ετησίως;","Εκτίμηση κινδύνου λοιμώξεων","",1,false,[]],["PCI.5","Εφαρμόζονται και μετρώνται οι δέσμες μέτρων για CLABSI, CAUTI, VAP και SSI;","Δείκτες δεσμών, επιτήρηση","",2,true,["clinical"]],["PCI.6","Καθαρίζονται, απολυμαίνονται και αποστειρώνονται σωστά τα ιατρικά εργαλεία και ο εξοπλισμός;","Αρχεία ΚΑΠ, έλεγχοι ενδοσκοπίων","",2,true,[]],["PCI.7","Διαχειρίζονται με ασφάλεια τα μολυσματικά απόβλητα και τα αιχμηρά;","Παρατήρηση περιεκτών, σύμβαση αποκομιδής","",1,false,[]],["PCI.7","Ελέγχονται η κουζίνα και ο ιματισμός για τον κίνδυνο λοιμώξεων;","Επιθεωρήσεις κουζίνας και πλυντηρίου","",1,false,[]],["PCI.8","Εφαρμόζονται προφυλάξεις απομόνωσης ανάλογα με τον τρόπο μετάδοσης, με διαθέσιμα ΜΑΠ;","Παρατήρηση θαλάμων απομόνωσης","",2,true,["clinical"]],["PCI.8","Ελέγχεται ο κίνδυνος λοιμώξεων στις κατασκευές και ανακαινίσεις (ICRA);","Αξιολογήσεις ICRA","",1,false,[]],["PCI.9","Προστατεύεται το προσωπικό (εμβολιασμοί, έκθεση σε αιχμηρά, προφύλαξη μετά από έκθεση);","Αρχεία υγείας προσωπικού","",1,false,[]]]},{"r":"GLD","t":"Διακυβέρνηση, ηγεσία και διεύθυνση","q":[["GLD.1","Είναι καθορισμένη η δομή διακυβέρνησης και οι ευθύνες της, και εγκρίνει τον στρατηγικό σχεδιασμό και το πρόγραμμα ποιότητας;","Καταστατικό, πρακτικά ΔΣ","",1,false,["management"]],["GLD.3","Σχεδιάζουν οι επικεφαλής τις υπηρεσίες με βάση τις ανάγκες του πληθυσμού και παρακολουθούν τις συμβάσεις τους;","Επιχειρησιακό σχέδιο, έλεγχος συμβάσεων","",1,false,["management"]],["GLD.4","Συμμετέχουν οι επικεφαλής τμημάτων στην επιλογή δεικτών και στη βελτίωση;","Πρακτικά, δείκτες τμήματος","",1,false,[]],["GLD.5","Εγκρίνεται και παρακολουθείται ο προϋπολογισμός με κριτήρια ποιότητας και ασφάλειας;","Προϋπολογισμός","",1,false,["management"]],["GLD.7","Αξιολογείται η ποιότητα των υπηρεσιών που παρέχονται με σύμβαση (υπεργολάβοι);","Αξιολογήσεις συμβάσεων","",1,false,["management"]],["GLD.9","Προωθείται κουλτούρα ασφάλειας με μέτρηση (έρευνα κουλτούρας) και αντιμετώπιση ανάρμοστων συμπεριφορών;","Έρευνα κουλτούρας, κώδικας συμπεριφοράς","",1,false,["management"]],["GLD.12","Υπάρχει πλαίσιο δεοντολογίας για κλινικά και διοικητικά διλήμματα (επιτροπή δεοντολογίας);","Πρακτικά επιτροπής δεοντολογίας","",1,false,["management"]]]},{"r":"FMS","t":"Εγκαταστάσεις και ασφάλεια","q":[["FMS.1","Υπάρχει πρόγραμμα διαχείρισης εγκαταστάσεων με εκτίμηση κινδύνων που επικαιροποιείται;","Πρόγραμμα FMS, εκτίμηση κινδύνων","",1,false,["management"]],["FMS.4","Είναι ασφαλής ο χώρος για ασθενείς, προσωπικό και επισκέπτες (έλεγχος πρόσβασης, σήμανση, ταυτότητες);","Επιθεώρηση χώρων","",1,false,[]],["FMS.5","Αποθηκεύονται και διαχειρίζονται με ασφάλεια τα επικίνδυνα υλικά, με δελτία δεδομένων ασφαλείας διαθέσιμα;","Μητρώο επικίνδυνων υλικών, SDS","",1,false,[]],["FMS.6","Υπάρχει σχέδιο αντιμετώπισης καταστροφών και γίνονται ασκήσεις;","Σχέδιο, αναφορές ασκήσεων","",1,false,["management"]],["FMS.7","Γνωρίζει το προσωπικό τι κάνει σε πυρκαγιά (RACE / PASS), είναι προσβάσιμες οι έξοδοι και ελεγμένοι οι πυροσβεστήρες;","Ασκήσεις πυρασφάλειας, ετικέτες πυροσβεστήρων","",1,true,[]],["FMS.8","Επιθεωρείται, ελέγχεται και συντηρείται ο ιατρικός εξοπλισμός, με διαχείριση ανακλήσεων;","Μητρώο εξοπλισμού, αρχεία συντήρησης","",1,false,[]],["FMS.9","Δοκιμάζονται τακτικά τα κρίσιμα συστήματα (εφεδρική ηλεκτροδότηση, ιατρικά αέρια, νερό) με εφεδρικές πηγές;","Αρχεία δοκιμών γεννήτριας και αερίων","",1,true,[]],["FMS.9","Παρακολουθείται η ποιότητα του νερού (Legionella, αιμοκάθαρση);","Αναλύσεις νερού","",1,false,[]]]},{"r":"SQE","t":"Προσόντα και εκπαίδευση προσωπικού","q":[["SQE.1","Έχει κάθε θέση γραπτή περιγραφή με τα απαιτούμενα προσόντα;","Περιγραφές θέσεων","",1,false,[]],["SQE.3","Αξιολογείται η επάρκεια του προσωπικού κατά την πρόσληψη και τουλάχιστον ετησίως;","Ατομικοί φάκελοι, αξιολογήσεις","",1,true,[]],["SQE.4","Περιλαμβάνει ο ατομικός φάκελος άδεια, πτυχία, εκπαιδεύσεις και αξιολογήσεις, επαληθευμένα από την πηγή;","Δείγμα φακέλων προσωπικού","",1,false,[]],["SQE.6","Έχει το προσωπικό εκπαίδευση σε βασική υποστήριξη ζωής ανανεωμένη ανά δύο χρόνια;","Πιστοποιητικά BLS / ALS","",2,true,["clinical"]],["SQE.8","Υπάρχει πρόγραμμα υγείας και ασφάλειας του προσωπικού (εμβολιασμοί, εργονομία, βία στον χώρο εργασίας);","Πρόγραμμα ιατρού εργασίας","",1,false,[]],["SQE.9","Επαληθεύονται τα διαπιστευτήρια των ιατρών και τους χορηγούνται κλινικά προνόμια που ανανεώνονται;","Φάκελοι προνομίων ιατρών","",1,true,["management"]],["SQE.11","Αξιολογείται συνεχώς η επαγγελματική απόδοση των ιατρών (OPPE) με δεδομένα;","Αξιολογήσεις OPPE","",1,false,["management"]],["SQE.13","Επαληθεύονται τα προσόντα και αξιολογείται η απόδοση του νοσηλευτικού προσωπικού;","Φάκελοι νοσηλευτών","",1,false,[]]]},{"r":"MOI","t":"Διαχείριση επικοινωνίας και πληροφοριών","q":[["MOI.1","Επικοινωνεί το νοσοκομείο αποτελεσματικά με την κοινότητα και τους ασθενείς για τις υπηρεσίες του;","Ιστοσελίδα, ενημερωτικό υλικό","",1,false,[]],["MOI.2","Προστατεύονται το απόρρητο, η ασφάλεια και η ακεραιότητα των δεδομένων (πρόσβαση ανά ρόλο, αντίγραφα ασφαλείας);","Πολιτική ασφάλειας πληροφοριών","",1,true,[]],["MOI.4","Χρησιμοποιούνται τυποποιημένοι κωδικοί διάγνωσης και πράξεων και μόνο εγκεκριμένες συντομογραφίες;","Λίστα συντομογραφιών","",1,false,[]],["MOI.7","Ελέγχονται τα έγγραφα (πολιτικές, διαδικασίες) για έγκριση, ανασκόπηση, διανομή και απόσυρση;","Λίστα ελεγχόμενων εγγράφων","",1,false,[]],["MOI.9","Ταυτοποιεί κάθε καταχώριση στον φάκελο ποιος την έκανε και πότε;","Δείγμα φακέλων","",1,false,["clinical"]],["MOI.10","Ανασκοπείται τακτικά ο ιατρικός φάκελος για πληρότητα, ακρίβεια και επικαιρότητα;","Έλεγχοι πληρότητας φακέλων","",1,false,[]],["MOI.13","Υπάρχει σχέδιο για τη συνέχεια λειτουργίας σε διακοπή των πληροφοριακών συστημάτων (downtime);","Διαδικασία downtime, δοκιμές","",1,false,["management"]]]}]}'::jsonb j),
tp as (insert into public.quality_audit_templates (organization_id, is_system, template_key, standard, standard_version, title, description, scope, department_types, active, version, source)
 select null, true, j->>'k', j->>'s', j->>'v', j->>'t', 'Βοήθημα επιθεώρησης για το ' || (j->>'t') || ': ερωτήσεις διατυπωμένες με δικά μας λόγια, με αναφορά στο άρθρο ή το κεφάλαιο. Δεν αποτελεί το κείμενο του προτύπου, που παραμένει η πηγή αναφοράς. Επεξεργάσιμο: δημιουργήστε αντίγραφο για το νοσοκομείο σας και προσαρμόστε το.', j->>'sc', array(select jsonb_array_elements_text(j->'dt')), true, 1, 'seed' from s
 on conflict on constraint quality_audit_templates_title_key do nothing returning id),
qs as (select ch.value->>'r' r, ch.value->>'t' t, q.value v, row_number() over (order by ch.ordinality, q.ordinality) p
 from s, jsonb_array_elements(j->'ch') with ordinality ch, jsonb_array_elements(ch.value->'q') with ordinality q)
insert into public.quality_audit_template_questions (template_id, organization_id, position, chapter_ref, chapter_title, clause_ref, question, guidance, evidence, weight, critical, areas)
select tp.id, null, qs.p, qs.r, qs.t, qs.v->>0, qs.v->>1, nullif(qs.v->>3, ''), nullif(qs.v->>2, ''), (qs.v->>4)::numeric, (qs.v->>5)::boolean, array(select jsonb_array_elements_text(qs.v->6)) from tp, qs;
